local __modules, __cache = {}, {}
local function require(name)
	local cached = __cache[name]
	if cached ~= nil then
		return cached
	end
	local factory = __modules[name]
	if not factory then
		error("ZaridiumUI: unknown module '" .. tostring(name) .. "'", 2)
	end
	local value = factory()
	__cache[name] = value
	return value
end

__modules["Util"] = function()
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")

local Util = {}

--// Shared runtime state (written by Library, read by components) \\--
Util.AnimationsEnabled = true
Util.RippleEnabled = true
Util.Speed = 1 -- global animation speed multiplier
Util.Scale = 1 -- current UIScale of the root frame

Util.Motion = {
	Instant = 0,
	Short = 0.12,
	Medium = 0.25,
	Long = 0.4,
	Emphasized = Enum.EasingStyle.Quint,
	Standard = Enum.EasingStyle.Quad,
}

--// Signal \\--
local Signal = {}
Signal.__index = Signal

function Signal.new()
	return setmetatable({ _handlers = {} }, Signal)
end

function Signal:Connect(fn)
	local handlers = self._handlers
	local connection = { Connected = true }
	local entry = { fn = fn, connection = connection }
	table.insert(handlers, entry)
	function connection:Disconnect()
		if not self.Connected then
			return
		end
		self.Connected = false
		local index = table.find(handlers, entry)
		if index then
			table.remove(handlers, index)
		end
	end
	return connection
end

function Signal:Once(fn)
	local connection
	connection = self:Connect(function(...)
		connection:Disconnect()
		fn(...)
	end)
	return connection
end

function Signal:Fire(...)
	for _, entry in table.clone(self._handlers) do
		task.spawn(entry.fn, ...)
	end
end

function Signal:Destroy()
	table.clear(self._handlers)
end

Util.Signal = Signal

--// Maid \\--
local Maid = {}
Maid.__index = Maid

function Maid.new()
	return setmetatable({ _tasks = {} }, Maid)
end

function Maid:Give(item)
	table.insert(self._tasks, item)
	return item
end

function Maid:Clean()
	local tasks = self._tasks
	self._tasks = {}
	for _, item in tasks do
		local kind = typeof(item)
		if kind == "RBXScriptConnection" then
			item:Disconnect()
		elseif kind == "Instance" then
			item:Destroy()
		elseif kind == "function" then
			pcall(item)
		elseif kind == "table" then
			if item.Disconnect then
				item:Disconnect()
			elseif item.Destroy then
				item:Destroy()
			end
		end
	end
end

Maid.Destroy = Maid.Clean

Util.Maid = Maid

--// Instances \\--
function Util.New(className, props, children)
	local instance = Instance.new(className)
	local parent
	if props then
		for key, value in props do
			if key == "Parent" then
				parent = value
			else
				instance[key] = value
			end
		end
	end
	if children then
		for _, child in children do
			child.Parent = instance
		end
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

function Util.Tween(instance, duration, props, style, direction)
	if not Util.AnimationsEnabled or not duration or duration <= 0 then
		for key, value in props do
			instance[key] = value
		end
		return nil
	end
	local tween = TweenService:Create(
		instance,
		TweenInfo.new(
			duration / math.max(Util.Speed, 0.01),
			style or Util.Motion.Emphasized,
			direction or Enum.EasingDirection.Out
		),
		props
	)
	tween:Play()
	return tween
end

--// Input helpers \\--
function Util.IsPointer(input)
	local kind = input.UserInputType
	return kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch
end

-- Returns a position in the same space as GuiObject.AbsolutePosition (ScreenGui with IgnoreGuiInset).
function Util.PointerPosition(input)
	if input.UserInputType == Enum.UserInputType.Touch then
		local inset = GuiService:GetGuiInset()
		return Vector2.new(input.Position.X + inset.X, input.Position.Y + inset.Y)
	end
	return UserInputService:GetMouseLocation()
end

--// Math / color \\--
function Util.Clamp(value, minimum, maximum)
	return math.clamp(value, minimum, maximum)
end

function Util.Round(value, step)
	if not step or step <= 0 then
		return value
	end
	return math.floor(value / step + 0.5) * step
end

function Util.FormatNumber(value, decimals)
	decimals = decimals or 0
	if decimals <= 0 then
		return tostring(math.floor(value + 0.5))
	end
	local text = string.format("%." .. decimals .. "f", value)
	return text
end

function Util.ToHex(color)
	return string.format(
		"#%02X%02X%02X",
		math.floor(color.R * 255 + 0.5),
		math.floor(color.G * 255 + 0.5),
		math.floor(color.B * 255 + 0.5)
	)
end

function Util.FromHex(text)
	if typeof(text) ~= "string" then
		return nil
	end
	local hex = text:gsub("^#", "")
	if #hex == 3 then
		hex = hex:gsub(".", "%0%0")
	end
	if #hex ~= 6 or hex:find("%X") then
		return nil
	end
	return Color3.fromRGB(
		tonumber(hex:sub(1, 2), 16) :: number,
		tonumber(hex:sub(3, 4), 16) :: number,
		tonumber(hex:sub(5, 6), 16) :: number
	)
end

function Util.DeepCopy(value)
	if typeof(value) ~= "table" then
		return value
	end
	local copy = {}
	for key, inner in value do
		copy[key] = Util.DeepCopy(inner)
	end
	return copy
end

function Util.Merge(base, overrides)
	local result = Util.DeepCopy(base)
	if overrides then
		for key, value in overrides do
			if typeof(value) == "table" and typeof(result[key]) == "table" and getmetatable(value) == nil then
				result[key] = Util.Merge(result[key], value)
			else
				result[key] = value
			end
		end
	end
	return result
end

-- Fills missing keys of `target` from `defaults` (one level deep for nested plain tables).
function Util.WithDefaults(target, defaults)
	target = target or {}
	for key, value in defaults do
		if target[key] == nil then
			target[key] = Util.DeepCopy(value)
		elseif typeof(value) == "table" and typeof(target[key]) == "table" and getmetatable(value) == nil then
			Util.WithDefaults(target[key], value)
		end
	end
	return target
end

return Util

end

__modules["Color"] = function()
-- Material 3 style color scheme generator.
-- Tonal palettes are built in OKLCH (perceptual) with the tone mapped to CIELAB L*, so the
-- Material contrast guarantees (tone 40 vs 100, 80 vs 20, ...) hold without a full HCT port.

local Color = {}

local function toLinear(c: number): number
	if c <= 0.04045 then
		return c / 12.92
	end
	return ((c + 0.055) / 1.055) ^ 2.4
end

local function toSrgb(c: number): number
	if c <= 0.0031308 then
		return 12.92 * c
	end
	return 1.055 * (c ^ (1 / 2.4)) - 0.055
end

-- sRGB (0..1) -> OKLab
local function rgbToOKLab(r: number, g: number, b: number): (number, number, number)
	r, g, b = toLinear(r), toLinear(g), toLinear(b)
	local l = (0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b) ^ (1 / 3)
	local m = (0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b) ^ (1 / 3)
	local s = (0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b) ^ (1 / 3)
	return 0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
		1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
		0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s
end

-- OKLab -> linear sRGB (may be out of gamut)
local function oklabToLinear(L: number, a: number, b: number): (number, number, number)
	local l = (L + 0.3963377774 * a + 0.2158037573 * b) ^ 3
	local m = (L - 0.1055613458 * a - 0.0638541728 * b) ^ 3
	local s = (L - 0.0894841775 * a - 1.2914855480 * b) ^ 3
	return 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
		-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
		-0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s
end

local function inGamut(r: number, g: number, b: number): boolean
	return r >= -0.0005 and g >= -0.0005 and b >= -0.0005 and r <= 1.0005 and g <= 1.0005 and b <= 1.0005
end

local function toneToL(tone: number): number
	if tone <= 0 then
		return 0
	elseif tone >= 100 then
		return 1
	elseif tone > 8 then
		return (tone + 16) / 116
	end
	return (tone / 903.2963) ^ (1 / 3)
end

local function clamp01(x: number): number
	return math.clamp(x, 0, 1)
end

-- Returns r, g, b (sRGB 0..1) for a hue (deg), chroma (OKLCH) and tone (0..100), reducing chroma to fit sRGB.
function Color.ToneRGB(hue: number, chroma: number, tone: number): (number, number, number)
	local L = toneToL(tone)
	local h = math.rad(hue)
	local ca, sb = math.cos(h), math.sin(h)
	local r, g, b = oklabToLinear(L, ca * chroma, sb * chroma)
	if not inGamut(r, g, b) then
		local lo, hi = 0, chroma
		for _ = 1, 18 do
			local mid = (lo + hi) / 2
			local mr, mg, mb = oklabToLinear(L, ca * mid, sb * mid)
			if inGamut(mr, mg, mb) then
				lo = mid
			else
				hi = mid
			end
		end
		r, g, b = oklabToLinear(L, ca * lo, sb * lo)
	end
	return clamp01(toSrgb(math.max(r, 0))), clamp01(toSrgb(math.max(g, 0))), clamp01(toSrgb(math.max(b, 0)))
end

function Color.Tone(hue, chroma, tone)
	local r, g, b = Color.ToneRGB(hue, chroma, tone)
	return Color3.new(r, g, b)
end

-- Returns hue (deg), chroma, lightness of a color in OKLCH.
function Color.Analyze(color)
	local L, a, b = rgbToOKLab(color.R, color.G, color.B)
	return math.deg(math.atan2(b, a)) % 360, math.sqrt(a * a + b * b), L
end

--// Role tables: { palette, tone } \\--
-- p primary, s secondary, t tertiary, n neutral, v neutral-variant, e error, g success, w warning

local DARK = {
