__modules["Core"] = function()
-- Shared runtime state: theme roles + live binding, shape scale, flags and popups.

local Util = require("Util")
local Color = require("Color")

local RunService = game:GetService("RunService")

local Core = {
	Roles = {},
	Mode = "Dark",
	Seed = Color3.fromHex("#6750A4"),
	Preset = "Violet",
	Overrides = {},
	CornerScale = 1,
	Radius = { None = 0, XSmall = 4, Small = 8, Medium = 12, Large = 16, XLarge = 28 },

	Flags = {},
	Options = {},
	Controls = {}, -- every live control, flagged or not, so Unload can disconnect their input listeners
	Listening = false,
	Keybinds = {},
	Popups = {},

	ThemeChanged = Util.Signal.new(),
	Maid = Util.Maid.new(),

	ScreenGui = nil,
	Overlay = nil,
	Window = nil,
}

-- instance -> { property -> role }
local bound = setmetatable({}, { __mode = "k" })
-- UICorner -> base radius in px
local corners = setmetatable({}, { __mode = "k" })
local themeConnection = nil

local function resolve(role)
	local kind = typeof(role)
	if kind == "string" then
		local color = Core.Roles[role]
		if color == nil then
			warn("[ZaridiumUI] unknown color role '" .. role .. "'")
			return Color3.new(1, 0, 1)
		end
		return color
	elseif kind == "function" then
		return role(Core.Roles)
	end
	return role
end

Core.Resolve = resolve

-- Sets a color property now and keeps it in sync with the theme. `role` is a role name, a Color3 or fn(roles) -> Color3.
function Core.Bind(instance, property, role)
	local props = bound[instance]
	if not props then
		props = {}
		bound[instance] = props
	end
	props[property] = role
	instance[property] = resolve(role)
end

-- Like Bind, but tweens to the new role (used for state changes such as selected/unselected).
function Core.Set(instance, property, role, duration)
	local props = bound[instance]
	if not props then
		props = {}
		bound[instance] = props
	end
	props[property] = role
	local color = resolve(role)
	if duration and duration > 0 then
		Util.Tween(instance, duration, { [property] = color }, Enum.EasingStyle.Quad)
	else
		instance[property] = color
	end
end

function Core.Unbind(instance)
	bound[instance] = nil
end

function Core.Corner(parent, radius)
	local corner = Instance.new("UICorner")
	if radius == "Full" then
		corner.CornerRadius = UDim.new(1, 0)
	else
		local base = Core.Radius[radius] or radius or 0
		corners[corner] = base
		corner.CornerRadius = UDim.new(0, math.floor(base * Core.CornerScale + 0.5))
	end
	corner.Parent = parent
	return corner
end

function Core.SetCornerScale(scale)
	Core.CornerScale = math.clamp(scale, 0, 2)
	for corner, base in corners do
		corner.CornerRadius = UDim.new(0, math.floor(base * Core.CornerScale + 0.5))
	end
end

--// Theme \\--
function Core.BuildRoles()
	local roles = Color.Generate(Core.Seed, Core.Mode)
	for role, color in Core.Overrides do
		if roles[role] ~= nil then
			roles[role] = color
		end
	end
	return roles
end

function Core.ApplyTheme(animate)
	Core.Roles = Core.BuildRoles()

	if themeConnection then
		themeConnection:Disconnect()
		themeConnection = nil
	end

	local entries = {}
	for instance, props in bound do
		for property, role in props do
			local ok, from = pcall(function()
				return instance[property]
			end)
			if ok and typeof(from) == "Color3" then
				table.insert(entries, { instance, property, from, resolve(role) })
			end
		end
	end

	if animate and Util.AnimationsEnabled and #entries <= 3000 then
		local started = os.clock()
		local duration = 0.3 / math.max(Util.Speed, 0.01)
		themeConnection = RunService.Heartbeat:Connect(function()
			local alpha = math.clamp((os.clock() - started) / duration, 0, 1)
			local eased = 1 - (1 - alpha) ^ 3
			for _, entry in entries do
				entry[1][entry[2]] = entry[3]:Lerp(entry[4], eased)
			end
			if alpha >= 1 and themeConnection then
				themeConnection:Disconnect()
				themeConnection = nil
			end
		end)
	else
		for _, entry in entries do
			entry[1][entry[2]] = entry[4]
		end
	end

	Core.ThemeChanged:Fire(Core.Roles)
end

-- options: Mode, Preset (name), Seed (Color3 or "#hex"), Overrides (role -> Color3)
function Core.SetTheme(options, animate)
	if options.Mode and Color.Schemes[options.Mode] then
		Core.Mode = options.Mode
	end
	if options.Preset then
		local preset = Color.FindPreset(options.Preset)
		if preset then
			Core.Preset = preset.Name
			Core.Seed = Color3.fromHex(preset.Seed)
		end
	end
	if options.Seed then
		local seed = options.Seed
		if typeof(seed) == "string" then
			seed = Util.FromHex(seed)
		end
		if typeof(seed) == "Color3" then
			Core.Seed = seed
			if not options.Preset then
				Core.Preset = "Custom"
			end
		end
	end
	if options.Overrides then
		Core.Overrides = options.Overrides
	end
	Core.ApplyTheme(animate ~= false)
end

--// Popups (dropdown menus, pickers) \\--
function Core.RegisterPopup(close)
	table.insert(Core.Popups, close)
end

function Core.UnregisterPopup(close)
	local index = table.find(Core.Popups, close)
	if index then
		table.remove(Core.Popups, index)
	end
end

local justClosed = {}

function Core.ClosePopups(except, byOutsideClick)
	for _, close in table.clone(Core.Popups) do
		if close ~= except then
			if byOutsideClick then
				justClosed[close] = os.clock()
			end
			close()
		end
	end
end

-- True when `close` was closed by an outside click in the last 0.35s (stops the same click from reopening it).
function Core.WasJustClosed(close)
	local at = justClosed[close]
	return at ~= nil and os.clock() - at < 0.35
end

-- Replaced by the Library once the overlay exists.
function Core.ShowTooltip(_text: string, _host: GuiObject) end
function Core.HideTooltip(_host: GuiObject?) end

Core.Roles = Core.BuildRoles()

return Core

end

__modules["Assets"] = function()
-- Downloads, validates and caches the bundled fonts + icon atlas, with safe fallbacks.
-- Nothing here ever throws: if the executor cannot cache files, the library falls back to
-- Roblox's built-in Gotham family and text-only icons.

local HttpService = game:GetService("HttpService")

-- Executor globals are optional; capture them once as `any` and guard with canCache().
local writefile: any, readfile: any, isfile: any, isfolder: any, makefolder: any, getcustomasset: any =
	writefile, readfile, isfile, isfolder, makefolder, getcustomasset

local Assets = {
	Ready = false,
	Cached = false, -- true when the Google Sans Flex fonts were loaded
	Rounded = true,
	Atlas = "",
	Status = "not initialised",
	Registry = setmetatable({}, { __mode = "k" }),
}

local WEIGHTS = {
	Regular = Enum.FontWeight.Regular,
	Medium = Enum.FontWeight.Medium,
	SemiBold = Enum.FontWeight.SemiBold,
	Bold = Enum.FontWeight.Bold,
}
local FACE_ORDER = { "Regular", "Medium", "SemiBold", "Bold" }
local FACE_WEIGHT = { Regular = 400, Medium = 500, SemiBold = 600, Bold = 700 }
local FALLBACK_FAMILY = "rbxasset://fonts/families/GothamSSm.json"

local families = { Standard = nil, Rounded = nil } -- uri strings
local customFont = nil
local fontCache = {}

local function isTtf(data)
	return #data > 1000 and (data:sub(1, 4) == "\0\1\0\0" or data:sub(1, 4) == "true" or data:sub(1, 4) == "OTTO")
end

local function isPng(data)
	return #data > 100 and data:sub(1, 4) == "\137PNG"
end

local function canCache()
	return writefile ~= nil and readfile ~= nil and isfile ~= nil and makefolder ~= nil and getcustomasset ~= nil
end

local function ensureFolder(path)
	if not isfolder(path) then
		makefolder(path)
	end
end

local function fetch(folder, baseUrl, remote, localName, validate)
	local path = folder .. "/" .. localName
	if isfile(path) then
		local ok, data = pcall(readfile, path)
		if ok and typeof(data) == "string" and validate(data) then
			return path
		end
	end
	local ok, data = pcall(function()
		return (game :: any):HttpGet(baseUrl .. remote, true)
	end)
	if ok and typeof(data) == "string" and validate(data) then
		local wrote = pcall(writefile, path, data)
		if wrote then
			return path
		end
	end
	return nil
end

local function buildFamily(folder, baseUrl, prefix, jsonName)
	local faces = {}
	for _, name in FACE_ORDER do
		local file = prefix .. "-" .. name .. ".ttf"
		local path = fetch(folder, baseUrl, "fonts/" .. file, file, isTtf)
		if not path then
			return nil
		end
		local ok, asset = pcall(getcustomasset, path)
		if not ok or typeof(asset) ~= "string" or asset == "" then
			return nil
		end
		table.insert(faces, { name = name, weight = FACE_WEIGHT[name], style = "normal", assetId = asset })
	end
	local jsonPath = folder .. "/" .. jsonName
	local wrote = pcall(writefile, jsonPath, HttpService:JSONEncode({ name = prefix, faces = faces }))
	if not wrote then
		return nil
	end
	local ok, uri = pcall(getcustomasset, jsonPath)
	if ok and typeof(uri) == "string" and uri ~= "" then
		return uri
	end
	return nil
end

-- config: AssetBaseUrl, CacheFolder, Version, RoundedFont, Font (Font), AtlasImage (string), Offline (bool)
function Assets.Init(config)
	config = config or {}
	Assets.Rounded = config.RoundedFont ~= false
	table.clear(fontCache)
	families.Standard, families.Rounded, customFont = nil, nil, nil

	if typeof(config.Font) == "Font" then
		customFont = config.Font
	end
	if typeof(config.AtlasImage) == "string" and config.AtlasImage ~= "" then
		Assets.Atlas = config.AtlasImage
	end

	if config.Offline or not canCache() then
		Assets.Status = config.Offline and "offline mode" or "executor has no file/asset API"
		Assets.Ready = true
		return
	end

	local baseUrl = config.AssetBaseUrl or "https://raw.githubusercontent.com/MidasRX/Zaridium/main/ui/assets/"
	if baseUrl:sub(-1) ~= "/" then
		baseUrl ..= "/"
	end
	local root = config.CacheFolder or "ZaridiumUI"
	local folder = root .. "/assets-" .. tostring(config.Version or "1")

	local prepared = pcall(function()
		ensureFolder(root)
		ensureFolder(folder)
	end)
	if not prepared then
		Assets.Status = "could not create cache folder"
		Assets.Ready = true
		return
	end

	if not customFont then
		local okStd, std = pcall(buildFamily, folder, baseUrl, "GoogleSansFlex", "family-standard.json")
		local okRnd, rnd = pcall(buildFamily, folder, baseUrl, "GoogleSansFlexRounded", "family-rounded.json")
		families.Standard = okStd and std or nil
		families.Rounded = okRnd and rnd or nil
		Assets.Cached = families.Standard ~= nil or families.Rounded ~= nil
	end

	if Assets.Atlas == "" then
		local path = fetch(folder, baseUrl, "icons/atlas.png", "atlas.png", isPng)
		if path then
			local ok, asset = pcall(getcustomasset, path)
			if ok and typeof(asset) == "string" then
				Assets.Atlas = asset
			end
		end
	end

	Assets.Status = string.format(
		"fonts=%s icons=%s",
		customFont and "custom" or (Assets.Cached and "Google Sans Flex" or "fallback"),
		Assets.Atlas ~= "" and "atlas" or "none"
	)
	Assets.Ready = true
end

function Assets.Font(weight)
	weight = weight or "Regular"
	local key = weight .. (Assets.Rounded and "R" or "S")
	local cached = fontCache[key]
	if cached then
		return cached
	end
	local enumWeight = WEIGHTS[weight] or Enum.FontWeight.Regular
	local font
	if customFont then
		font = Font.new(customFont.Family, enumWeight, Enum.FontStyle.Normal)
	else
		local uri = (Assets.Rounded and families.Rounded) or families.Standard or families.Rounded or FALLBACK_FAMILY
		font = Font.new(uri, enumWeight, Enum.FontStyle.Normal)
	end
	fontCache[key] = font
	return font
end

-- Applies the font to a text object and keeps it updated when the font style changes.
function Assets.Apply(textObject, weight)
	Assets.Registry[textObject] = weight
	textObject.FontFace = Assets.Font(weight)
end

function Assets.SetRounded(enabled)
	Assets.Rounded = enabled and true or false
	for object, weight in pairs(Assets.Registry) do
		object.FontFace = Assets.Font(weight)
	end
end

return Assets

end

__modules["Icons"] = function()
-- Material Symbols atlas lookup. Icons are white glyphs; tint with ImageColor3 (bound to a theme role).

local Core = require("Core")
local Assets = require("Assets")
local IconData = require("IconData")

local Icons = {}

function Icons.Resolve(name)
	if typeof(name) ~= "string" then
		return nil
	end
	local key = string.lower(name):gsub("[%s%-]", "_")
	local alias = IconData.Aliases[key]
	if alias then
		key = alias
	end
	return IconData.Icons[key] and key or nil
end

function Icons.Has(name)
	return Icons.Resolve(name) ~= nil
end

function Icons.List()
	local names = {}
	for name in IconData.Icons do
		table.insert(names, name)
	end
	table.sort(names)
	return names
end

-- Points an ImageLabel/ImageButton at an icon. Accepts an icon name, an asset id number or an "rbxassetid://" string.
function Icons.Apply(image, name, filled)
	local kind = typeof(name)
	if kind == "number" then
		image.Image = "rbxassetid://" .. name
		image.ImageRectOffset = Vector2.zero
		image.ImageRectSize = Vector2.zero
		return true
	elseif kind == "string" and (name:find("^rbxassetid://") or name:find("^rbxasset://") or name:find("^http")) then
		image.Image = name
		image.ImageRectOffset = Vector2.zero
		image.ImageRectSize = Vector2.zero
		return true
	end

	local key = Icons.Resolve(name)
	if not key or Assets.Atlas == "" then
		image.Image = ""
		return false
	end
	local cell = IconData.Icons[key][filled and "f" or "o"]
	image.Image = Assets.Atlas
	image.ImageRectOffset = Vector2.new(cell[1], cell[2])
	image.ImageRectSize = Vector2.new(IconData.Cell, IconData.Cell)
	return true
end

-- Creates an icon ImageLabel. props: Name, Size (px number), Color (role/Color3), Filled, Position, AnchorPoint, Parent, ZIndex
function Icons.Create(name, props)
	props = props or {}
	local size = props.Size or 24
	local image = Instance.new("ImageLabel")
	image.Name = props.Name or "Icon"
	image.BackgroundTransparency = 1
	image.BorderSizePixel = 0
	image.Size = UDim2.fromOffset(size, size)
	image.Position = props.Position or UDim2.new()
	image.AnchorPoint = props.AnchorPoint or Vector2.zero
	image.ZIndex = props.ZIndex or 2
	image.ScaleType = Enum.ScaleType.Fit
	if props.LayoutOrder then
		image.LayoutOrder = props.LayoutOrder
	end
	Core.Bind(image, "ImageColor3", props.Color or "OnSurfaceVariant")
	local ok = Icons.Apply(image, name, props.Filled)
	image.Visible = ok or name == nil
	image.Parent = props.Parent
	return image
end

return Icons

end

__modules["Components"] = function()
-- Low-level Material 3 building blocks: typography, frames, state layers and ripples.

local Util = require("Util")
local Core = require("Core")
local Assets = require("Assets")
local Icons = require("Icons")

local UserInputService = game:GetService("UserInputService")

local Components = {}

--// Typography (Material 3 type scale) \\--
Components.Type = {
	HeadlineSmall = { 24, "Regular" },
	TitleLarge = { 22, "Medium" },
	TitleMedium = { 16, "SemiBold" },
	TitleSmall = { 14, "SemiBold" },
	LabelLarge = { 14, "Medium" },
	LabelMedium = { 12, "Medium" },
	LabelSmall = { 11, "Medium" },
	BodyLarge = { 16, "Regular" },
	BodyMedium = { 14, "Regular" },
	BodySmall = { 12, "Regular" },
}

-- props: Parent, Text, Style, Role, Size, Position, AnchorPoint, XAlign, YAlign, Wrap, AutoSize ("X"|"Y"|"XY"),
--        LayoutOrder, Truncate, ZIndex, Name
function Components.Text(props)
	local style = Components.Type[props.Style or "BodyMedium"] or Components.Type.BodyMedium
	local label = Instance.new("TextLabel")
	label.Name = props.Name or "Text"
	label.BackgroundTransparency = 1
	label.BorderSizePixel = 0
	label.Text = props.Text or ""
	label.TextSize = style[1]
	label.RichText = props.RichText == true
	label.TextXAlignment = props.XAlign or Enum.TextXAlignment.Left
	label.TextYAlignment = props.YAlign or Enum.TextYAlignment.Center
	label.TextWrapped = props.Wrap == true
	label.TextTruncate = props.Truncate and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None
	label.Size = props.Size or UDim2.new(1, 0, 0, style[1] + 6)
	label.Position = props.Position or UDim2.new()
	label.AnchorPoint = props.AnchorPoint or Vector2.zero
	label.ZIndex = props.ZIndex or 2
	label.LayoutOrder = props.LayoutOrder or 0
	if props.AutoSize == "X" then
		label.AutomaticSize = Enum.AutomaticSize.X
	elseif props.AutoSize == "Y" then
		label.AutomaticSize = Enum.AutomaticSize.Y
	elseif props.AutoSize == "XY" then
		label.AutomaticSize = Enum.AutomaticSize.XY
	end
	Assets.Apply(label, style[2])
	Core.Bind(label, "TextColor3", props.Role or "OnSurface")
	label.Parent = props.Parent
	return label
end

-- props: Name, Size, Position, AnchorPoint, Role (background color role), Transparency, Radius, Parent, Clip, LayoutOrder,
--        ZIndex, StrokeRole, StrokeThickness, AutoSize, Canvas (use CanvasGroup)
function Components.Frame(props)
	local frame = Instance.new(props.Canvas and "CanvasGroup" or "Frame")
	frame.Name = props.Name or "Frame"
	frame.BorderSizePixel = 0
	frame.Size = props.Size or UDim2.fromScale(1, 1)
	frame.Position = props.Position or UDim2.new()
	frame.AnchorPoint = props.AnchorPoint or Vector2.zero
	frame.ZIndex = props.ZIndex or 1
	frame.LayoutOrder = props.LayoutOrder or 0
	frame.ClipsDescendants = props.Clip == true
	if props.AutoSize == "Y" then
		frame.AutomaticSize = Enum.AutomaticSize.Y
	elseif props.AutoSize == "X" then
		frame.AutomaticSize = Enum.AutomaticSize.X
	elseif props.AutoSize == "XY" then
		frame.AutomaticSize = Enum.AutomaticSize.XY
	end
	if props.Role then
		Core.Bind(frame, "BackgroundColor3", props.Role)
		frame.BackgroundTransparency = props.Transparency or 0
	else
		frame.BackgroundTransparency = 1
	end
	if props.Radius then
		Core.Corner(frame, props.Radius)
	end
	if props.StrokeRole then
		local stroke = Instance.new("UIStroke")
		stroke.Thickness = props.StrokeThickness or 1
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		Core.Bind(stroke, "Color", props.StrokeRole)
		stroke.Parent = frame
	end
	frame.Parent = props.Parent
	return frame
end

function Components.Padding(parent, top, right, bottom, left)
	local padding = Instance.new("UIPadding")
	padding.PaddingTop = UDim.new(0, top or 0)
	padding.PaddingRight = UDim.new(0, right or top or 0)
	padding.PaddingBottom = UDim.new(0, bottom or top or 0)
	padding.PaddingLeft = UDim.new(0, left or right or top or 0)
	padding.Parent = parent
	return padding
end

function Components.List(parent, padding, direction, hAlign, vAlign)
	local layout = Instance.new("UIListLayout")
	layout.SortOrder = Enum.SortOrder.LayoutOrder
	layout.FillDirection = direction or Enum.FillDirection.Vertical
	layout.Padding = UDim.new(0, padding or 0)
	layout.HorizontalAlignment = hAlign or Enum.HorizontalAlignment.Left
	layout.VerticalAlignment = vAlign or Enum.VerticalAlignment.Top
	layout.Parent = parent
	return layout
end

--// Interaction: state layer + ripple + click \\--
-- host: the visible GuiObject. opts: Radius, StateRole (default "OnSurface"), Ripple (default true), Disabled,
--       OnClick(input), OnPress(), OnRelease(), OnHover(isHovering), Tooltip, ZIndex, CanFocus
function Components.Interactive(host, opts)
	opts = opts or {}
	local maid = Util.Maid.new()
	local self = {
		Host = host,
		Hovering = false,
		Pressing = false,
		Disabled = opts.Disabled == true,
		Clicked = Util.Signal.new(),
	}

	local layer = Components.Frame({
		Name = "StateLayer",
		Canvas = true,
		ZIndex = opts.ZIndex or 1,
	})
	layer.Parent = host
	if opts.Radius then
		Core.Corner(layer, opts.Radius)
	end

	local state = Components.Frame({ Name = "State", Role = opts.StateRole or "OnSurface", Transparency = 1 })
	state.Parent = layer

	local hit = Instance.new("TextButton")
	hit.Selectable = false
	hit.Name = "Hit"
	hit.BackgroundTransparency = 1
	hit.BorderSizePixel = 0
	hit.Text = ""
	hit.AutoButtonColor = false
	hit.Size = UDim2.fromScale(1, 1)
	hit.ZIndex = (opts.ZIndex or 1) + 8
	hit.Selectable = opts.CanFocus == true
	hit.Parent = host

	local function refresh()
		local transparency = 1
		if not self.Disabled then
			if self.Pressing then
				transparency = 0.88
			elseif self.Hovering then
				transparency = 0.92
			end
		end
		Util.Tween(state, Util.Motion.Short, { BackgroundTransparency = transparency }, Enum.EasingStyle.Quad)
	end

	local activeRipples = {}

	local function spawnRipple(pointer)
		if not Util.RippleEnabled or not Util.AnimationsEnabled or opts.Ripple == false then
			return
		end
		local size = layer.AbsoluteSize
		if size.X < 1 or size.Y < 1 then
			return
		end
		local scale = math.max(Util.Scale, 0.01)
		local local_ = (pointer - layer.AbsolutePosition) / scale
		local width, height = size.X / scale, size.Y / scale
		local radius = math.sqrt(
			math.max(local_.X, width - local_.X) ^ 2 + math.max(local_.Y, height - local_.Y) ^ 2
		)
		local circle = Components.Frame({
			Name = "Ripple",
			Role = opts.StateRole or "OnSurface",
			Transparency = 0.84,
			Size = UDim2.fromOffset(0, 0),
			Position = UDim2.fromOffset(local_.X, local_.Y),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Radius = "Full",
			ZIndex = 2,
		})
		circle.Parent = layer
		Util.Tween(
			circle,
			Util.Motion.Long,
			{ Size = UDim2.fromOffset(radius * 2, radius * 2) },
			Enum.EasingStyle.Quint
		)
		table.insert(activeRipples, circle)
		return circle
	end

	local function fadeRipples()
		local list = activeRipples
		activeRipples = {}
		for _, circle in list do
			Util.Tween(circle, Util.Motion.Long, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad)
			task.delay(Util.Motion.Long + 0.05, function()
				circle:Destroy()
			end)
		end
	end

	maid:Give(hit.MouseEnter:Connect(function()
		self.Hovering = true
		refresh()
		if opts.OnHover then
			opts.OnHover(true)
		end
		if opts.Tooltip then
			Core.ShowTooltip(opts.Tooltip, host)
		end
	end))
	maid:Give(hit.MouseLeave:Connect(function()
		self.Hovering = false
		self.Pressing = false
		refresh()
		fadeRipples()
		if opts.OnHover then
			opts.OnHover(false)
		end
		if opts.Tooltip then
			Core.HideTooltip(host)
		end
	end))
	maid:Give(hit.InputBegan:Connect(function(input)
		if self.Disabled or not Util.IsPointer(input) then
			return
		end
		self.Pressing = true
		refresh()
		spawnRipple(Util.PointerPosition(input))
		if opts.OnPress then
			opts.OnPress(input)
		end
	end))
	maid:Give(hit.InputEnded:Connect(function(input)
		if not Util.IsPointer(input) then
			return
		end
		if self.Pressing then
			self.Pressing = false
			refresh()
			fadeRipples()
			if opts.OnRelease then
				opts.OnRelease(input)
			end
		end
	end))
	maid:Give(hit.Activated:Connect(function(input)
		if self.Disabled then
			return
		end
		self.Clicked:Fire(input)
		if opts.OnClick then
			opts.OnClick(input)
		end
	end))

	function self:SetDisabled(disabled)
		self.Disabled = disabled and true or false
		hit.Active = not self.Disabled
		refresh()
	end

	function self:Destroy()
		maid:Clean()
		layer:Destroy()
		hit:Destroy()
	end

	self.Hit = hit
	self.Layer = layer
	return self
end

--// Common widgets \\--

-- Standalone icon button (round, 40px): props Parent, Icon, Size, Role, Tooltip, OnClick, Position, AnchorPoint
function Components.IconButton(props)
	local size = props.Size or 40
	local button = Components.Frame({
		Name = props.Name or "IconButton",
		Size = UDim2.fromOffset(size, size),
		Position = props.Position,
		AnchorPoint = props.AnchorPoint,
		Role = props.Background,
		Radius = "Full",
		Parent = props.Parent,
		LayoutOrder = props.LayoutOrder,
		ZIndex = props.ZIndex or 2,
	})
	local icon = Icons.Create(props.Icon, {
		Size = math.floor(size * 0.6),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Color = props.Role or "OnSurfaceVariant",
		Parent = button,
		ZIndex = (props.ZIndex or 2) + 1,
	})
	local interactive = Components.Interactive(button, {
		Radius = "Full",
		StateRole = props.StateRole or props.Role or "OnSurface",
		Tooltip = props.Tooltip,
		OnClick = props.OnClick,
		ZIndex = props.ZIndex or 2,
	})
	return button, icon, interactive
end

-- Tooltip lives in the overlay layer; Library wires it up through Core.
function Components.InstallTooltips(overlay)
	local tip = Components.Frame({
		Name = "Tooltip",
		Role = "InverseSurface",
		Radius = "XSmall",
		Size = UDim2.fromOffset(10, 28),
		AutoSize = "XY",
		ZIndex = 400,
		Parent = overlay,
	})
	tip.Visible = false
	Components.Padding(tip, 6, 10, 6, 10)
	local label = Components.Text({
		Parent = tip,
		Style = "BodySmall",
		Role = "InverseOnSurface",
		Size = UDim2.fromOffset(0, 16),
		AutoSize = "XY",
		ZIndex = 401,
	})
	local owner = nil
	local token = 0

	function Core.ShowTooltip(text, host)
		token += 1
		local mine = token
		owner = host
		task.delay(0.45, function()
			if mine ~= token or owner ~= host or not host.Parent then
				return
			end
			label.Text = text
			tip.Visible = true
		end)
	end

	function Core.HideTooltip(host)
		if owner == host or host == nil then
			token += 1
			owner = nil
			tip.Visible = false
		end
	end

	local scale = overlay:FindFirstChildOfClass("UIScale")
	local connection = UserInputService.InputChanged:Connect(function(input)
		if tip.Visible and input.UserInputType == Enum.UserInputType.MouseMovement then
			local s = scale and scale.Scale or 1
			local origin = overlay.AbsolutePosition
			local mouse = UserInputService:GetMouseLocation()
			tip.Position = UDim2.fromOffset((mouse.X - origin.X) / s + 14, (mouse.Y - origin.Y) / s + 18)
		end
	end)

	return tip, connection
end

return Components

end

__modules["Controls"] = function()
-- Controls: every Add* method that can be called on a Section (or any container that has been "attached").
-- All controls share one contract, see docs/API.md ("Control contract").

local Util = require("Util")
local Core = require("Core")
local Assets = require("Assets")
local Icons = require("Icons")
local Components = require("Components")

local UserInputService = game:GetService("UserInputService")

local Controls = {}

local Frame, Text, List, Padding = Components.Frame, Components.Text, Components.List, Components.Padding

--// Shared control scaffolding \\--
local function newControl(kind, opts, container)
	local self = {
		Type = kind,
		Flag = opts.Flag,
		Value = nil,
		Changed = Util.Signal.new(),
		Disabled = opts.Disabled == true,
		_hidden = opts.Visible == false,
		_filtered = false,
		_maid = Util.Maid.new(),
		_callback = opts.Callback,
		_setters = {},
	}

	function self:OnChanged(fn)
		return self.Changed:Connect(fn)
	end

	function self:_applyVisible()
		if self.Row then
			self.Row.Visible = not self._hidden and not self._filtered
		end
	end

	function self:SetVisible(visible)
		self._hidden = not visible
		self:_applyVisible()
	end

	function self:SetDisabled(disabled)
		self.Disabled = disabled and true or false
		if self._applyDisabled then
			self._applyDisabled(self.Disabled)
		end
	end

	function self:Get()
		return self.Value
	end

	function self:Serialize()
		return self.Value
	end

	function self:Deserialize(value, silent)
		self:Set(value, silent)
	end

	function self:_emit(silent)
		if silent then
			return
		end
		self.Changed:Fire(self.Value)
		if self._callback then
			task.spawn(self._callback, self.Value)
		end
	end

	Core.Controls[self] = true

	function self:Destroy()
		Core.Controls[self] = nil
		self._maid:Clean()
		self.Changed:Destroy()
		if self.Flag and Core.Options[self.Flag] == self then
			Core.Options[self.Flag] = nil
			Core.Flags[self.Flag] = nil
		end
		if self.Row then
			self.Row:Destroy()
		end
	end

	return self
end

local function register(self)
	if self.Flag then
		if Core.Options[self.Flag] and Core.Options[self.Flag] ~= self then
			warn("[ZaridiumUI] duplicate flag '" .. self.Flag .. "', the previous control was replaced")
		end
		Core.Options[self.Flag] = self
		Core.Flags[self.Flag] = self.Value
		self.Changed:Connect(function(value)
			Core.Flags[self.Flag] = value
		end)
	end
end

-- Creates the row frame with optional leading icon, title and description. Returns row, rightHolder, textBlock.
local function makeRow(container, opts, minHeight)
	local hasDescription = opts.Description ~= nil and opts.Description ~= ""
	local row = Frame({
		Name = opts.Flag or opts.Text or "Row",
		Size = UDim2.new(1, 0, 0, hasDescription and math.max(minHeight, 64) or minHeight),
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	local content = Frame({ Name = "Content", Size = UDim2.fromScale(1, 1), ZIndex = 3, Parent = row })
	Padding(content, 0, 16, 0, 16)

	local leftOffset = 0
	if opts.Icon then
		Icons.Create(opts.Icon, {
			Size = 24,
			Position = UDim2.new(0, 0, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			Color = "OnSurfaceVariant",
			Parent = content,
		})
		leftOffset = 40
	end

	local right = Frame({
		Name = "Right",
		Size = UDim2.new(0, 0, 1, 0),
		Position = UDim2.fromScale(1, 0),
		AnchorPoint = Vector2.new(1, 0),
		AutoSize = "X",
		Parent = content,
	})

	local block = Frame({
		Name = "Text",
		Position = UDim2.fromOffset(leftOffset, 0),
		Size = UDim2.new(1, -leftOffset, 1, 0),
		Parent = content,
	})
	local layout = List(block, 2, nil, nil, Enum.VerticalAlignment.Center)
	layout.Name = "Layout"

	local title = Text({
		Name = "Title",
		Parent = block,
		Text = opts.Text or "",
		Style = "BodyLarge",
		Size = UDim2.new(1, 0, 0, 22),
		Truncate = true,
	})
	local description
	if hasDescription then
		description = Text({
			Name = "Description",
			Parent = block,
			Text = opts.Description,
			Style = "BodySmall",
			Role = "OnSurfaceVariant",
			Size = UDim2.new(1, 0, 0, 0),
			Wrap = true,
			AutoSize = "Y",
			LayoutOrder = 1,
		})
		-- The row keeps a fixed height that follows the measured text. An AutomaticSize row holding a
		-- scale-sized child makes Roblox grow the row in a feedback loop (rows ended up 500+ px tall).
		local function fit()
			local scale = math.max(Util.Scale, 0.01)
			local needed = 20 + 22 + 2 + description.AbsoluteSize.Y / scale
			row.Size = UDim2.new(1, 0, 0, math.max(minHeight, math.ceil(needed)))
		end
		description:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
		task.defer(fit)
	end
	if opts.Visible == false then
		row.Visible = false
	end
	return row, right, block, title, description, content
end

local function reserveRight(block, right, extra)
	-- keep the text block clear of the right-hand control
	right:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		local scale = math.max(Util.Scale, 0.01)
		block.Size = UDim2.new(block.Size.X.Scale, block.Size.X.Offset, 1, 0)
		local parentWidth = block.Parent.AbsoluteSize.X / scale
		local used = right.AbsoluteSize.X / scale + (extra or 12)
		local left = block.Position.X.Offset
		block.Size = UDim2.new(0, math.max(parentWidth - used - left, 20), 1, 0)
	end)
end

local function bindDisabled(self, ...)
	local targets = { ... }
	self._applyDisabled = function(disabled)
		for _, target in targets do
			Util.Tween(target, Util.Motion.Short, {
				[target:IsA("TextLabel") and "TextTransparency" or "ImageTransparency"] = disabled and 0.62 or 0,
			}, Enum.EasingStyle.Quad)
		end
	end
	if self.Disabled then
		self._applyDisabled(true)
	end
end

--// Label / paragraph \\--
function Controls.AddLabel(container, opts)
	if typeof(opts) == "string" then
		opts = { Text = opts }
	end
	local self = newControl("Label", opts, container)
	local row = Frame({
		Name = "Label",
		Size = UDim2.new(1, 0, 0, 0),
		AutoSize = "Y",
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	Padding(row, 8, 16, 8, 16)
	local label = Text({
		Parent = row,
		Text = opts.Text or "",
		Style = opts.Style or "BodyMedium",
		Role = opts.Role or "OnSurfaceVariant",
		Size = UDim2.new(1, 0, 0, 0),
		AutoSize = "Y",
		Wrap = true,
		RichText = opts.RichText,
		XAlign = opts.Center and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left,
	})
	self.Row = row
	self.Label = label
	self.Value = opts.Text or ""
	function self:Set(text)
		self.Value = tostring(text)
		label.Text = self.Value
	end
	self.SetText = self.Set
	function self:Serialize()
		return nil
	end
	if opts.Visible == false then
		row.Visible = false
	end
	return self
end

function Controls.AddDivider(container, opts)
	opts = opts or {}
	local self = newControl("Divider", opts, container)
	local row = Frame({
		Name = "Divider",
		Size = UDim2.new(1, 0, 0, 17),
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	self.Line = Frame({
		Role = "OutlineVariant",
		Size = UDim2.new(1, -(opts.Inset == false and 0 or 32), 0, 1),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Parent = row,
	})
	self.Row = row
	function self:Serialize()
		return nil
	end
	self:_applyVisible()
	return self
end

--// Button \\--
-- Style: "Filled" (default) | "Tonal" | "Outlined" | "Text" | "Elevated" | "Danger"
function Controls.AddButton(container, opts)
	local self = newControl("Button", opts, container)
	local style = opts.Style or "Tonal"
	local holder = Frame({
		Name = opts.Text or "Button",
		Size = UDim2.new(1, 0, 0, 56),
		Parent = container,
	})
	holder.LayoutOrder = opts.LayoutOrder or 0
	Padding(holder, 8, 16, 8, 16)

	local background, content, strokeRole
	if style == "Filled" then
		background, content = "Primary", "OnPrimary"
	elseif style == "Danger" then
		background, content = "Error", "OnError"
	elseif style == "Outlined" then
		background, content, strokeRole = nil, "Primary", "Outline"
	elseif style == "Text" then
		background, content = nil, "Primary"
	elseif style == "Elevated" then
		background, content = "SurfaceContainerLow", "Primary"
	else
		background, content = "SecondaryContainer", "OnSecondaryContainer"
	end

	local button = Frame({
		Name = "Button",
		Size = UDim2.fromScale(1, 1),
		Role = background,
		Radius = "Full",
		StrokeRole = strokeRole,
		Parent = holder,
	})
	local inner = Frame({ Name = "Content", Size = UDim2.fromScale(1, 1), Parent = button, ZIndex = 3 })
	List(inner, 8, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Center, Enum.VerticalAlignment.Center)
	local icon
	if opts.Icon then
		icon = Icons.Create(opts.Icon, { Size = 18, Color = content, Parent = inner, ZIndex = 4, LayoutOrder = 0 })
	end
	local label = Text({
		Parent = inner,
		Text = opts.Text or "Button",
		Style = "LabelLarge",
		Role = content,
		Size = UDim2.fromOffset(0, 20),
		AutoSize = "X",
		XAlign = Enum.TextXAlignment.Center,
		ZIndex = 4,
		LayoutOrder = 1,
	})
	local interactive = Components.Interactive(button, {
		Radius = "Full",
		StateRole = content,
		Tooltip = opts.Tooltip,
		Disabled = self.Disabled,
		ZIndex = 2,
		OnClick = function()
			self:_emit(false)
		end,
	})
	self.Row = holder
	self.Interactive = interactive
	self.Value = nil
	function self:SetText(textValue)
		label.Text = tostring(textValue)
	end
	function self:Set()
		self:_emit(false)
	end
	function self:Serialize()
		return nil
	end
	bindDisabled(self, label)
	local baseApply = self._applyDisabled
	self._applyDisabled = function(disabled)
		interactive:SetDisabled(disabled)
		baseApply(disabled)
		if icon then
			Util.Tween(icon, Util.Motion.Short, { ImageTransparency = disabled and 0.62 or 0 }, Enum.EasingStyle.Quad)
		end
	end
	if self.Disabled then
		self._applyDisabled(true)
	end
	if opts.Visible == false then
		holder.Visible = false
	end
	return self
end

--// Toggle (Material 3 switch) \\--
function Controls.AddToggle(container, opts)
	local self = newControl("Toggle", opts, container)
	local row, right, block, title = makeRow(container, opts, 56)
	self.Row = row
	self.Value = opts.Default == true

	local track = Frame({
		Name = "Track",
		Size = UDim2.fromOffset(52, 32),
		Position = UDim2.fromScale(1, 0.5),
		AnchorPoint = Vector2.new(1, 0.5),
		Role = "SurfaceContainerHighest",
		Radius = "Full",
		StrokeRole = "Outline",
		StrokeThickness = 2,
		Parent = right,
	})
	right.Size = UDim2.new(0, 52, 1, 0)
	local stroke = track:FindFirstChildOfClass("UIStroke")
	local thumb = Frame({
		Name = "Thumb",
		Size = UDim2.fromOffset(16, 16),
		Position = UDim2.new(0, 16, 0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = "Outline",
		Radius = "Full",
		ZIndex = 3,
		Parent = track,
	})
	local check = Icons.Create("check", {
		Size = 16,
		Color = "OnPrimaryContainer",
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Parent = thumb,
		ZIndex = 4,
	})
	check.ImageTransparency = 1

	local function render(animate)
		local on = self.Value
		local duration = animate and Util.Motion.Medium or 0
		Core.Set(track, "BackgroundColor3", on and "Primary" or "SurfaceContainerHighest", duration)
		Core.Set(stroke, "Color", on and "Primary" or "Outline", duration)
		Core.Set(thumb, "BackgroundColor3", on and "OnPrimary" or "Outline", duration)
		local size = on and 24 or 16
		local x = on and 36 or 16
		Util.Tween(thumb, duration, {
			Size = UDim2.fromOffset(size, size),
			Position = UDim2.new(0, x, 0.5, 0),
		}, Enum.EasingStyle.Back)
		Util.Tween(check, duration, { ImageTransparency = on and 0 or 1 }, Enum.EasingStyle.Quad)
	end
	render(false)

	function self:Set(value, silent)
		value = value == true
		if value == self.Value then
			return
		end
		self.Value = value
		render(true)
		self:_emit(silent)
	end

	local interactive = Components.Interactive(row, {
		Radius = "Medium",
		Tooltip = opts.Tooltip,
		Disabled = self.Disabled,
		ZIndex = 1,
		OnClick = function()
			self:Set(not self.Value)
		end,
	})
	bindDisabled(self, title)
	local baseApply = self._applyDisabled
	self._applyDisabled = function(disabled)
		interactive:SetDisabled(disabled)
		baseApply(disabled)
		track.BackgroundTransparency = disabled and 0.6 or 0
	end
	reserveRight(block, right, 16)
	register(self)
	if opts.Default and opts.Callback then
		task.spawn(opts.Callback, self.Value)
	end
	return self
end

--// Slider \\--
function Controls.AddSlider(container, opts)
	local self = newControl("Slider", opts, container)
	local minimum, maximum = opts.Min or 0, opts.Max or 100
	local step = opts.Step or 1
	local decimals = opts.Decimals or ((step < 1) and (#tostring(step) - 2) or 0)
	local suffix = opts.Suffix or ""

	local row = Frame({
		Name = opts.Flag or opts.Text or "Slider",
		Size = UDim2.new(1, 0, 0, 64),
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	Padding(row, 8, 16, 8, 16)
	self.Row = row

	local top = Frame({ Name = "Top", Size = UDim2.new(1, 0, 0, 24), Parent = row })
	local leftOffset = 0
	if opts.Icon then
		Icons.Create(opts.Icon, { Size = 20, Position = UDim2.fromOffset(0, 2), Parent = top })
		leftOffset = 30
	end
	local title = Text({
		Parent = top,
		Text = opts.Text or "",
		Style = "BodyLarge",
		Size = UDim2.new(1, -leftOffset - 80, 1, 0),
		Position = UDim2.fromOffset(leftOffset, 0),
		Truncate = true,
	})
	local valueLabel = Text({
		Parent = top,
		Style = "LabelLarge",
		Role = "Primary",
		Size = UDim2.new(0, 80, 1, 0),
		Position = UDim2.fromScale(1, 0),
		AnchorPoint = Vector2.new(1, 0),
		XAlign = Enum.TextXAlignment.Right,
	})

	local trackHolder = Frame({
		Name = "TrackHolder",
		Size = UDim2.new(1, 0, 0, 24),
		Position = UDim2.new(0, 0, 0, 28),
		Parent = row,
	})
	local inactive = Frame({
		Name = "Inactive",
		Size = UDim2.new(1, 0, 0, 6),
		Position = UDim2.fromScale(0, 0.5),
		AnchorPoint = Vector2.new(0, 0.5),
		Role = "SecondaryContainer",
		Radius = "Full",
		Parent = trackHolder,
	})
	local active = Frame({
		Name = "Active",
		Size = UDim2.fromScale(0, 1),
		Role = "Primary",
		Radius = "Full",
		Parent = inactive,
	})
	local handle = Frame({
		Name = "Handle",
		Size = UDim2.fromOffset(20, 20),
		Position = UDim2.fromScale(0, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = "Primary",
		Radius = "Full",
		ZIndex = 3,
		Parent = inactive,
	})
	local halo = Frame({
		Name = "Halo",
		Size = UDim2.fromOffset(20, 20),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = "Primary",
		Transparency = 1,
		Radius = "Full",
		ZIndex = 2,
		Parent = handle,
	})

	local function format(value)
		local text
		if opts.Format then
			text = opts.Format(value)
		else
			text = Util.FormatNumber(value, decimals) .. suffix
		end
		return text
	end

	local function render(animate)
		local alpha = (self.Value - minimum) / math.max(maximum - minimum, 1e-9)
		valueLabel.Text = format(self.Value)
		local duration = animate and 0.08 or 0
		Util.Tween(active, duration, { Size = UDim2.fromScale(alpha, 1) }, Enum.EasingStyle.Quad)
		Util.Tween(handle, duration, { Position = UDim2.fromScale(alpha, 0.5) }, Enum.EasingStyle.Quad)
	end

	self.Value = math.clamp(Util.Round(opts.Default or minimum, step), minimum, maximum)
	render(false)

	function self:Set(value, silent)
		value = math.clamp(Util.Round(tonumber(value) or minimum, step), minimum, maximum)
		if decimals > 0 then
			value = tonumber(Util.FormatNumber(value, decimals)) or value
		end
		if value == self.Value then
			return
		end
		self.Value = value
		render(true)
		self:_emit(silent)
	end

	local dragging = false
	local function update(input)
		local width = inactive.AbsoluteSize.X
		if width < 1 then
			return
		end
		local alpha = math.clamp((Util.PointerPosition(input).X - inactive.AbsolutePosition.X) / width, 0, 1)
		self:Set(minimum + (maximum - minimum) * alpha)
	end

	local hit = Instance.new("TextButton")
	hit.Selectable = false
	hit.Name = "Hit"
	hit.BackgroundTransparency = 1
	hit.Text = ""
	hit.AutoButtonColor = false
	hit.Size = UDim2.new(1, 20, 1, 8)
	hit.Position = UDim2.fromOffset(-10, -4)
	hit.ZIndex = 9
	hit.Parent = trackHolder

	local function setHalo(active_)
		Util.Tween(halo, Util.Motion.Short, {
			Size = active_ and UDim2.fromOffset(40, 40) or UDim2.fromOffset(20, 20),
			BackgroundTransparency = active_ and 0.84 or 1,
		}, Enum.EasingStyle.Quad)
	end
	self._maid:Give(hit.InputBegan:Connect(function(input)
		if self.Disabled or not Util.IsPointer(input) then
			return
		end
		dragging = true
		setHalo(true)
		update(input)
	end))
	self._maid:Give(UserInputService.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			update(input)
		end
	end))
	self._maid:Give(UserInputService.InputEnded:Connect(function(input)
		if dragging and Util.IsPointer(input) then
			dragging = false
			setHalo(false)
		end
	end))
	self._maid:Give(hit.MouseEnter:Connect(function()
		if not dragging and not self.Disabled then
			setHalo(true)
		end
		if opts.Tooltip then
			Core.ShowTooltip(opts.Tooltip, row)
		end
	end))
	self._maid:Give(hit.MouseLeave:Connect(function()
		if not dragging then
			setHalo(false)
		end
		if opts.Tooltip then
			Core.HideTooltip(row)
		end
	end))

	bindDisabled(self, title, valueLabel)
	if opts.Visible == false then
		row.Visible = false
	end
	register(self)
	return self
end

--// Text input \\--
function Controls.AddInput(container, opts)
	local self = newControl("Input", opts, container)
	self.Value = opts.Default or ""

	local row = Frame({
		Name = opts.Flag or opts.Text or "Input",
		Size = UDim2.new(1, 0, 0, 72),
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	Padding(row, 8, 16, 8, 16)
	self.Row = row

	local field = Frame({
		Name = "Field",
		Size = UDim2.fromScale(1, 1),
		Radius = "XSmall",
		StrokeRole = "Outline",
		Parent = row,
	})
	local stroke = field:FindFirstChildOfClass("UIStroke")

	-- Floating label sits on the border when focused or filled (outlined text field).
	local labelBack = Frame({
		Name = "LabelBack",
		Size = UDim2.fromOffset(0, 12),
		AutoSize = "X",
		Position = UDim2.new(0, 12, 0, 0),
		AnchorPoint = Vector2.new(0, 0.5),
		Role = "Surface",
		ZIndex = 4,
		Parent = field,
	})
	Padding(labelBack, 0, 4, 0, 4)
	labelBack.BackgroundTransparency = 1
	local label = Text({
		Parent = labelBack,
		Text = opts.Text or "",
		Style = "BodyLarge",
		Role = "OnSurfaceVariant",
		Size = UDim2.fromOffset(0, 16),
		AutoSize = "X",
		ZIndex = 5,
	})

	local box = Instance.new("TextBox")
	box.Name = "Box"
	box.BackgroundTransparency = 1
	box.BorderSizePixel = 0
	box.ClearTextOnFocus = false
	box.PlaceholderText = ""
	box.Text = self.Value
	box.TextSize = 16
	box.TextXAlignment = Enum.TextXAlignment.Left
	box.TextTruncate = Enum.TextTruncate.AtEnd
	box.Size = UDim2.new(1, -28, 1, 0)
	box.Position = UDim2.fromOffset(14, 0)
	box.ZIndex = 5
	Assets.Apply(box, "Regular")
	Core.Bind(box, "TextColor3", "OnSurface")
	Core.Bind(box, "PlaceholderColor3", "OnSurfaceVariant")
	box.Parent = field
	if opts.Numeric then
		box:GetPropertyChangedSignal("Text"):Connect(function()
			local filtered = box.Text:gsub("[^%d%.%-]", "")
			if filtered ~= box.Text then
				box.Text = filtered
			end
		end)
	end
	if opts.MaxLength then
		box:GetPropertyChangedSignal("Text"):Connect(function()
			if #box.Text > opts.MaxLength then
				box.Text = box.Text:sub(1, opts.MaxLength)
			end
		end)
	end

	local focused = false
	local function renderLabel(animate)
		local floating = focused or box.Text ~= ""
		local duration = animate and Util.Motion.Short or 0
		if floating then
			labelBack.BackgroundTransparency = 0
			Util.Tween(labelBack, duration, { Position = UDim2.new(0, 12, 0, 0) }, Enum.EasingStyle.Quad)
			label.TextSize = 12
			Core.Set(label, "TextColor3", focused and "Primary" or "OnSurfaceVariant", duration)
			Util.Tween(label, duration, { Size = UDim2.fromOffset(0, 14) })
		else
			labelBack.BackgroundTransparency = 1
			Util.Tween(labelBack, duration, { Position = UDim2.new(0, 12, 0.5, 0) }, Enum.EasingStyle.Quad)
			label.TextSize = 16
			Core.Set(label, "TextColor3", "OnSurfaceVariant", duration)
		end
		Core.Set(stroke, "Color", focused and "Primary" or "Outline", duration)
		stroke.Thickness = focused and 2 or 1
	end
	renderLabel(false)
	if opts.Placeholder then
		box.PlaceholderText = opts.Placeholder
	end

	self._maid:Give(box.Focused:Connect(function()
		focused = true
		renderLabel(true)
	end))
	self._maid:Give(box.FocusLost:Connect(function(enterPressed)
		focused = false
		local value = box.Text
		if opts.Numeric then
			local number = tonumber(value)
			if opts.Min and number then
				number = math.max(number, opts.Min)
			end
			if opts.Max and number then
				number = math.min(number, opts.Max)
			end
			value = number and tostring(number) or tostring(self.Value)
			box.Text = value
		end
		renderLabel(true)
		if opts.Finished == false or enterPressed or opts.Finished == nil then
			self:Set(value)
		end
	end))

	function self:Set(value, silent)
		value = tostring(value or "")
		if box.Text ~= value then
			box.Text = value
		end
		renderLabel(true)
		if value == self.Value then
			return
		end
		self.Value = value
		self:_emit(silent)
	end

	self._applyDisabled = function(disabled)
		box.TextEditable = not disabled
		box.TextTransparency = disabled and 0.6 or 0
	end
	if self.Disabled then
		self._applyDisabled(true)
	end
	if opts.Visible == false then
		row.Visible = false
	end
	register(self)
	return self
end

--// Dropdown (menu in the overlay layer) \\--
function Controls.AddDropdown(container, opts)
	local self = newControl("Dropdown", opts, container)
	local multi = opts.Multi == true
	local values = opts.Values or {}
	self.Values = values
	if multi then
		self.Value = {}
		if typeof(opts.Default) == "table" then
			for _, v in opts.Default do
				self.Value[v] = true
			end
		end
	else
		self.Value = opts.Default
		if self.Value == nil and not opts.AllowNull then
			self.Value = values[1]
		end
	end

	local row = Frame({
		Name = opts.Flag or opts.Text or "Dropdown",
		Size = UDim2.new(1, 0, 0, 72),
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	Padding(row, 8, 16, 8, 16)
	self.Row = row

	local field = Frame({
		Name = "Field",
		Size = UDim2.fromScale(1, 1),
		Radius = "XSmall",
		StrokeRole = "Outline",
		Parent = row,
	})
	local stroke = field:FindFirstChildOfClass("UIStroke")
	local labelBack = Frame({
		Size = UDim2.fromOffset(0, 12),
		AutoSize = "X",
		Position = UDim2.new(0, 12, 0, 0),
		AnchorPoint = Vector2.new(0, 0.5),
		Role = "Surface",
		ZIndex = 4,
		Parent = field,
	})
	Padding(labelBack, 0, 4, 0, 4)
	Text({
		Parent = labelBack,
		Text = opts.Text or "",
		Style = "BodySmall",
		Role = "OnSurfaceVariant",
		Size = UDim2.fromOffset(0, 14),
		AutoSize = "X",
		ZIndex = 5,
	})
	local valueText = Text({
		Parent = field,
		Style = "BodyLarge",
		Size = UDim2.new(1, -52, 1, 0),
		Position = UDim2.fromOffset(14, 0),
		Truncate = true,
		ZIndex = 5,
	})
	local chevron = Icons.Create("expand_more", {
		Size = 24,
		Position = UDim2.new(1, -12, 0.5, 0),
		AnchorPoint = Vector2.new(1, 0.5),
		Parent = field,
		ZIndex = 5,
	})

	local function display()
		if multi then
			local selected = {}
			for _, v in self.Values do
				if self.Value[v] then
					table.insert(selected, tostring(v))
				end
			end
			valueText.Text = #selected == 0 and (opts.Placeholder or "None") or table.concat(selected, ", ")
		else
			valueText.Text = self.Value ~= nil and tostring(self.Value) or (opts.Placeholder or "None")
		end
	end
	display()

	local menu, closeMenu
	local open = false

	local function selectValue(value)
		if multi then
			self.Value[value] = not self.Value[value] or nil
			display()
			self:_emit(false)
		else
			if self.Value ~= value then
				self.Value = value
				display()
				self:_emit(false)
			end
			closeMenu()
		end
	end

	local function buildMenu()
		local overlay = Core.Overlay
		local scale = math.max(Util.Scale, 0.01)
		local width = field.AbsoluteSize.X / scale
		local itemHeight = 48
		local count = #self.Values
		local visibleCount = math.min(count, opts.MaxVisible or 6)
		local height = visibleCount * itemHeight + 16

		menu = Frame({
			Name = "DropdownMenu",
			Canvas = true,
			Size = UDim2.fromOffset(width, 0),
			Role = "SurfaceContainer",
			Radius = "XSmall",
			ZIndex = 300,
			Parent = overlay,
		})
		local menuStroke = Instance.new("UIStroke")
		menuStroke.Thickness = 1
		Core.Bind(menuStroke, "Color", "OutlineVariant")
		menuStroke.Parent = menu

		local origin = overlay.AbsolutePosition
		local fieldPos = (field.AbsolutePosition - origin) / scale
		local overlayHeight = overlay.AbsoluteSize.Y / scale
		local below = fieldPos.Y + field.AbsoluteSize.Y / scale + 4
		local flip = below + height > overlayHeight - 8
		local y = flip and (fieldPos.Y - 4 - height) or below
		menu.Position = UDim2.fromOffset(fieldPos.X, y)
		menu.AnchorPoint = Vector2.new(0, flip and 1 or 0)
		if flip then
			menu.Position = UDim2.fromOffset(fieldPos.X, fieldPos.Y - 4)
		end

		local scroller = Instance.new("ScrollingFrame")
		scroller.Name = "Items"
		scroller.BackgroundTransparency = 1
		scroller.BorderSizePixel = 0
		scroller.Size = UDim2.fromScale(1, 1)
		scroller.ScrollBarThickness = 3
		scroller.CanvasSize = UDim2.new()
		scroller.AutomaticCanvasSize = Enum.AutomaticSize.Y
		scroller.ZIndex = 301
		Core.Bind(scroller, "ScrollBarImageColor3", "Outline")
		scroller.Parent = menu
		Padding(scroller, 8, 0, 8, 0)
		List(scroller, 0)

		for index, value in self.Values do
			local item = Frame({
				Name = "Item",
				Size = UDim2.new(1, 0, 0, itemHeight),
				Role = "SecondaryContainer",
				Transparency = 1,
				ZIndex = 302,
				Parent = scroller,
			})
			item.LayoutOrder = index
			local isSelected = multi and self.Value[value] or (not multi and self.Value == value)
			if isSelected and not multi then
				item.BackgroundTransparency = 0
			end
			local textColor = (isSelected and not multi) and "OnSecondaryContainer" or "OnSurface"
			local itemLabel = Text({
				Parent = item,
				Text = tostring(value),
				Style = "BodyLarge",
				Role = textColor,
				Size = UDim2.new(1, -56, 1, 0),
				Position = UDim2.fromOffset(16, 0),
				Truncate = true,
				ZIndex = 303,
			})
			local mark
			if multi or isSelected then
				mark = Icons.Create("check", {
					Size = 20,
					Color = multi and "Primary" or "OnSecondaryContainer",
					Position = UDim2.new(1, -16, 0.5, 0),
					AnchorPoint = Vector2.new(1, 0.5),
					Parent = item,
					ZIndex = 303,
				})
				mark.Visible = isSelected and true or false
			end
			Components.Interactive(item, {
				StateRole = textColor,
				ZIndex = 302,
				OnClick = function()
					selectValue(value)
					if multi then
						local now = self.Value[value] and true or false
						if mark then
							mark.Visible = now
						end
					end
				end,
			})
			local _ = itemLabel
		end

		menu.Size = UDim2.fromOffset(width, 0)
		Util.Tween(menu, Util.Motion.Medium, { Size = UDim2.fromOffset(width, height) }, Enum.EasingStyle.Quint)
	end

	function closeMenu()
		if not open then
			return
		end
		open = false
		Core.UnregisterPopup(closeMenu)
		Util.Tween(chevron, Util.Motion.Medium, { Rotation = 0 }, Enum.EasingStyle.Quint)
		Core.Set(stroke, "Color", "Outline", Util.Motion.Short)
		stroke.Thickness = 1
		local m = menu
		menu = nil
		if m then
			local tween = Util.Tween(m, Util.Motion.Short, { Size = UDim2.fromOffset(m.Size.X.Offset, 0) }, Enum.EasingStyle.Quad)
			task.delay(tween and Util.Motion.Short or 0, function()
				m:Destroy()
			end)
		end
	end

	local function openMenu()
		if open or self.Disabled then
			return
		end
		Core.ClosePopups()
		open = true
		Core.RegisterPopup(closeMenu)
		Util.Tween(chevron, Util.Motion.Medium, { Rotation = 180 }, Enum.EasingStyle.Quint)
		Core.Set(stroke, "Color", "Primary", Util.Motion.Short)
		stroke.Thickness = 2
		buildMenu()
	end

	local interactive = Components.Interactive(field, {
		Radius = "XSmall",
		Tooltip = opts.Tooltip,
		ZIndex = 6,
		OnClick = function()
			if open then
				closeMenu()
			elseif not Core.WasJustClosed(closeMenu) then
				openMenu()
			end
		end,
	})

	self.Open = function()
		openMenu()
	end
	self.Close = function()
		closeMenu()
	end

	function self:Set(value, silent)
		if multi then
			local newValue = {}
			if typeof(value) == "table" then
				for k, v in value do
					if typeof(k) == "number" then
						newValue[v] = true
					elseif v then
						newValue[k] = true
					end
				end
			end
			self.Value = newValue
		else
			if value ~= nil and not table.find(self.Values, value) then
				return
			end
			if value == self.Value then
				return
			end
			self.Value = value
		end
		display()
		self:_emit(silent)
	end

	function self:SetValues(newValues, keepSelection)
		self.Values = newValues
		if not keepSelection or (not multi and not table.find(newValues, self.Value)) then
			if multi then
				self.Value = {}
			else
				self.Value = newValues[1]
			end
		end
		display()
		closeMenu()
	end

	function self:Serialize()
		if multi then
			local list = {}
			for _, v in self.Values do
				if self.Value[v] then
					table.insert(list, v)
				end
			end
			return list
		end
		return self.Value
	end

	function self:Deserialize(value)
		self:Set(value, true)
	end

	self._maid:Give(closeMenu)
	self._applyDisabled = function(disabled)
		interactive:SetDisabled(disabled)
		valueText.TextTransparency = disabled and 0.6 or 0
		if disabled then
			closeMenu()
		end
	end
	if self.Disabled then
		self._applyDisabled(true)
	end
	if opts.Visible == false then
		row.Visible = false
	end
	register(self)
	return self
end

--// Segmented button (single or multi select) \\--
function Controls.AddSegmented(container, opts)
	local self = newControl("Segmented", opts, container)
	local values = opts.Values or {}
	local multi = opts.Multi == true
	self.Values = values
	if multi then
		self.Value = {}
		if typeof(opts.Default) == "table" then
			for _, v in opts.Default do
				self.Value[v] = true
			end
		end
	else
		self.Value = opts.Default or values[1]
	end

	local hasTitle = opts.Text ~= nil and opts.Text ~= ""
	local row = Frame({
		Name = opts.Flag or opts.Text or "Segmented",
		Size = UDim2.new(1, 0, 0, hasTitle and 88 or 56),
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	Padding(row, 8, 16, 8, 16)
	self.Row = row

	if hasTitle then
		Text({ Parent = row, Text = opts.Text, Style = "BodyLarge", Size = UDim2.new(1, 0, 0, 24) })
	end
	local bar = Frame({
		Name = "Bar",
		Size = UDim2.new(1, 0, 0, 40),
		Position = UDim2.fromOffset(0, hasTitle and 32 or 0),
		Radius = "Full",
		StrokeRole = "Outline",
		Canvas = true,
		Parent = row,
	})
	bar:FindFirstChildOfClass("UIStroke").Thickness = 1
	local layout = List(bar, 0, Enum.FillDirection.Horizontal)

	local buttons = {}
	local function isSelected(value)
		if multi then
			return self.Value[value] == true
		end
		return self.Value == value
	end

	local function render(animate)
		for value, entry in buttons do
			local selected = isSelected(value)
			local duration = animate and Util.Motion.Short or 0
			Core.Set(entry.frame, "BackgroundColor3", "SecondaryContainer", duration)
			Util.Tween(entry.frame, duration, { BackgroundTransparency = selected and 0 or 1 }, Enum.EasingStyle.Quad)
			Core.Set(entry.label, "TextColor3", selected and "OnSecondaryContainer" or "OnSurface", duration)
			entry.check.Visible = selected
			Core.Set(entry.check, "ImageColor3", "OnSecondaryContainer", 0)
		end
	end

	local function layoutButtons()
		local count = math.max(#values, 1)
		for _, entry in buttons do
			entry.frame.Size = UDim2.new(1 / count, 0, 1, 0)
		end
	end

	for index, value in values do
		local frame = Frame({
			Name = tostring(value),
			Role = "SecondaryContainer",
			Transparency = 1,
			Size = UDim2.new(1 / math.max(#values, 1), 0, 1, 0),
			Parent = bar,
		})
		frame.LayoutOrder = index
		local inner = Frame({ Size = UDim2.fromScale(1, 1), ZIndex = 3, Parent = frame })
		List(inner, 6, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Center, Enum.VerticalAlignment.Center)
		local check = Icons.Create("check", { Size = 16, Parent = inner, ZIndex = 4, LayoutOrder = 0 })
		check.Visible = false
		local label = Text({
			Parent = inner,
			Text = tostring(value),
			Style = "LabelLarge",
			Size = UDim2.fromOffset(0, 20),
			AutoSize = "X",
			ZIndex = 4,
			LayoutOrder = 1,
		})
		buttons[value] = { frame = frame, label = label, check = check }
		Components.Interactive(frame, {
			StateRole = "OnSurface",
			ZIndex = 2,
			OnClick = function()
				if self.Disabled then
					return
				end
				if multi then
					self.Value[value] = not self.Value[value] or nil
					render(true)
					self:_emit(false)
				elseif self.Value ~= value then
					self.Value = value
					render(true)
					self:_emit(false)
				end
			end,
		})
	end
	layoutButtons()
	render(false)
	local _ = layout

	function self:Set(value, silent)
		if multi then
			local newValue = {}
			if typeof(value) == "table" then
				for k, v in value do
					if typeof(k) == "number" then
						newValue[v] = true
					elseif v then
						newValue[k] = true
					end
				end
			end
			self.Value = newValue
		else
			if not buttons[value] or value == self.Value then
				return
			end
			self.Value = value
		end
		render(true)
		self:_emit(silent)
	end

	function self:Serialize()
		if multi then
			local list = {}
			for _, v in values do
				if self.Value[v] then
					table.insert(list, v)
				end
			end
			return list
		end
		return self.Value
	end
	if opts.Visible == false then
		row.Visible = false
	end
	register(self)
	return self
end

--// Chips (filter chips: multi toggle) \\--
function Controls.AddChips(container, opts)
	opts.Multi = true
	local self = newControl("Chips", opts, container)
	local values = opts.Values or {}
	self.Values = values
	self.Value = {}
	if typeof(opts.Default) == "table" then
		for _, v in opts.Default do
			self.Value[v] = true
		end
	end

	local row = Frame({
		Name = opts.Flag or opts.Text or "Chips",
		Size = UDim2.new(1, 0, 0, 0),
		AutoSize = "Y",
		Parent = container,
	})
	row.LayoutOrder = opts.LayoutOrder or 0
	Padding(row, 8, 16, 8, 16)
	List(row, 8)
	self.Row = row
	if opts.Text and opts.Text ~= "" then
		Text({ Parent = row, Text = opts.Text, Style = "BodyLarge", Size = UDim2.new(1, 0, 0, 24) })
	end
	local flow = Frame({ Size = UDim2.new(1, 0, 0, 0), AutoSize = "Y", Parent = row })
	flow.LayoutOrder = 1
	local grid = Instance.new("UIListLayout")
	grid.FillDirection = Enum.FillDirection.Horizontal
	grid.Wraps = true
	grid.Padding = UDim.new(0, 8)
	grid.SortOrder = Enum.SortOrder.LayoutOrder
	grid.Parent = flow

	local chips = {}
	local function render(animate)
		for value, chip in chips do
			local selected = self.Value[value] == true
			local duration = animate and Util.Motion.Short or 0
			Util.Tween(chip.frame, duration, { BackgroundTransparency = selected and 0 or 1 }, Enum.EasingStyle.Quad)
			Core.Set(chip.label, "TextColor3", selected and "OnSecondaryContainer" or "OnSurfaceVariant", duration)
			chip.check.Visible = selected
			chip.stroke.Transparency = selected and 1 or 0
		end
	end
	for index, value in values do
		local frame = Frame({
			Name = tostring(value),
			Size = UDim2.fromOffset(0, 32),
			AutoSize = "X",
			Role = "SecondaryContainer",
			Transparency = 1,
			Radius = "Small",
			StrokeRole = "Outline",
			Parent = flow,
		})
		frame.LayoutOrder = index
		local stroke = frame:FindFirstChildOfClass("UIStroke")
		Padding(frame, 0, 12, 0, 12)
		local inner = Frame({ Size = UDim2.new(0, 0, 1, 0), AutoSize = "X", ZIndex = 3, Parent = frame })
		List(inner, 6, Enum.FillDirection.Horizontal, nil, Enum.VerticalAlignment.Center)
		local check = Icons.Create("check", { Size = 16, Color = "OnSecondaryContainer", Parent = inner, ZIndex = 4 })
		check.Visible = false
		check.LayoutOrder = 0
		local label = Text({
			Parent = inner,
			Text = tostring(value),
			Style = "LabelLarge",
			Role = "OnSurfaceVariant",
			Size = UDim2.fromOffset(0, 20),
			AutoSize = "X",
			ZIndex = 4,
			LayoutOrder = 1,
		})
		chips[value] = { frame = frame, label = label, check = check, stroke = stroke }
		Components.Interactive(frame, {
			Radius = "Small",
			StateRole = "OnSurface",
			ZIndex = 2,
			OnClick = function()
				if self.Disabled then
					return
				end
				self.Value[value] = not self.Value[value] or nil
				render(true)
				self:_emit(false)
			end,
		})
	end
	render(false)

	function self:Set(value, silent)
		local newValue = {}
		if typeof(value) == "table" then
			for k, v in value do
				if typeof(k) == "number" then
					newValue[v] = true
				elseif v then
					newValue[k] = true
				end
			end
		end
		self.Value = newValue
		render(true)
		self:_emit(silent)
	end
	function self:Serialize()
		local list = {}
		for _, v in values do
			if self.Value[v] then
				table.insert(list, v)
			end
		end
		return list
	end
	if opts.Visible == false then
		row.Visible = false
	end
	register(self)
	return self
end

--// Progress \\--
function Controls.AddProgress(container, opts)
	local self = newControl("Progress", opts, container)
	local row, right, block, _, _, content = makeRow(container, {
		Text = opts.Text,
		Description = opts.Description,
		Icon = opts.Icon,
		Flag = opts.Flag,
		LayoutOrder = opts.LayoutOrder,
		Visible = opts.Visible,
	}, 56)
	self.Row = row
	right.Size = UDim2.new(0, 56, 1, 0)
	local percent = Text({
		Parent = right,
		Style = "LabelLarge",
		Role = "Primary",
		Size = UDim2.fromScale(1, 1),
		XAlign = Enum.TextXAlignment.Right,
	})
	local barBack = Frame({
		Name = "Bar",
		Size = UDim2.new(1, 0, 0, 4),
		Position = UDim2.fromScale(0, 1),
		AnchorPoint = Vector2.new(0, 1),
		Role = "SecondaryContainer",
		Radius = "Full",
		Parent = content,
	})
	local fill = Frame({
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		Role = "Primary",
		Radius = "Full",
		Parent = barBack,
	})
	reserveRight(block, right, 8)
	self.Value = math.clamp(opts.Default or 0, 0, 1)
	local function render(animate)
		percent.Text = string.format("%d%%", math.floor(self.Value * 100 + 0.5))
		Util.Tween(fill, animate and Util.Motion.Medium or 0, { Size = UDim2.fromScale(self.Value, 1) })
	end
	render(false)
	function self:Set(value, silent)
		value = math.clamp(tonumber(value) or 0, 0, 1)
		if value == self.Value then
			return
		end
		self.Value = value
		render(true)
		self:_emit(silent)
	end
	function self:Serialize()
		return nil
	end
	return self
end

--// Keybind \\--
local KEY_NAMES = {
	LeftControl = "LCtrl",
	RightControl = "RCtrl",
	LeftShift = "LShift",
	RightShift = "RShift",
	LeftAlt = "LAlt",
	RightAlt = "RAlt",
	Return = "Enter",
	Backspace = "Backspace",
	Escape = "Esc",
	Space = "Space",
	Zero = "0",
	One = "1",
	Two = "2",
	Three = "3",
	Four = "4",
	Five = "5",
	Six = "6",
	Seven = "7",
	Eight = "8",
	Nine = "9",
}

local function keyName(key)
	if key == nil then
		return "None"
	end
	if typeof(key) == "EnumItem" then
		if key.EnumType == Enum.UserInputType then
			if key == Enum.UserInputType.MouseButton1 then
				return "Mouse 1"
			elseif key == Enum.UserInputType.MouseButton2 then
				return "Mouse 2"
			elseif key == Enum.UserInputType.MouseButton3 then
				return "Mouse 3"
			end
		end
		return KEY_NAMES[key.Name] or key.Name
	end
	return tostring(key)
end

Controls.KeyName = keyName

local function parseKey(value)
	if value == nil or value == "None" then
		return nil
	end
	if typeof(value) == "EnumItem" then
		return value
	end
	if typeof(value) == "string" then
		local keyCode = Enum.KeyCode[value]
		if keyCode then
			return keyCode
		end
		local ok, inputType = pcall(function()
			return Enum.UserInputType[value]
		end)
		if ok and inputType then
			return inputType
		end
	end
	return nil
end

-- Mode: "Press" (callback on press, default) | "Hold" (value true while held) | "Toggle" (value flips on press)
function Controls.AddKeybind(container, opts)
	local self = newControl("Keybind", opts, container)
	local row, right, block, title = makeRow(container, opts, 56)
	self.Row = row
	self.Mode = opts.Mode or "Press"
	self.Key = parseKey(opts.Default)
	if self.Mode ~= "Press" then
		self.Value = false
	end
	self.Pressed = Util.Signal.new()

	local chip = Frame({
		Name = "Chip",
		Size = UDim2.fromOffset(0, 32),
		AutoSize = "X",
		Position = UDim2.fromScale(1, 0.5),
		AnchorPoint = Vector2.new(1, 0.5),
		Role = "SurfaceContainerHighest",
		Radius = "Small",
		StrokeRole = "OutlineVariant",
		Parent = right,
	})
	Padding(chip, 0, 12, 0, 12)
	local keyLabel = Text({
		Parent = chip,
		Style = "LabelLarge",
		Size = UDim2.fromOffset(0, 32),
		AutoSize = "X",
		XAlign = Enum.TextXAlignment.Center,
		ZIndex = 3,
	})
	right.Size = UDim2.new(0, 80, 1, 0)

	local listening = false
	local function render()
		keyLabel.Text = listening and "Press a key…" or keyName(self.Key)
		Core.Set(chip, "BackgroundColor3", listening and "PrimaryContainer" or "SurfaceContainerHighest", Util.Motion.Short)
		Core.Set(keyLabel, "TextColor3", listening and "OnPrimaryContainer" or "OnSurface", Util.Motion.Short)
	end
	render()

	local interactive = Components.Interactive(chip, {
		Radius = "Small",
		StateRole = "OnSurface",
		Tooltip = opts.Tooltip or "Click, then press a key (Esc clears)",
		ZIndex = 2,
		OnClick = function()
			if self.Disabled then
				return
			end
			listening = true
			Core.Listening = true
			render()
		end,
	})

	local function trigger(down)
		if self.Mode == "Hold" then
			if self.Value ~= down then
				self.Value = down
				self:_emit(false)
			end
		elseif down then
			if self.Mode == "Toggle" then
				self.Value = not self.Value
				self:_emit(false)
			else
				self.Pressed:Fire()
				if self._callback then
					task.spawn(self._callback)
				end
			end
		end
	end

	local function matches(input)
		local key = self.Key
		if not key then
			return false
		end
		if key.EnumType == Enum.KeyCode then
			return input.KeyCode == key
		end
		return input.UserInputType == key
	end

	self._maid:Give(UserInputService.InputBegan:Connect(function(input, processed)
		if listening then
			if input.UserInputType == Enum.UserInputType.Keyboard then
				listening = false
				task.defer(function()
					Core.Listening = false
				end)
				if input.KeyCode == Enum.KeyCode.Escape then
					self.Key = nil
				else
					self.Key = input.KeyCode
				end
				render()
				self.Changed:Fire(self.Value)
			elseif input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.MouseButton3 then
				listening = false
				task.defer(function()
					Core.Listening = false
				end)
				self.Key = input.UserInputType
				render()
				self.Changed:Fire(self.Value)
			end
			return
		end
		if processed or self.Disabled then
			return
		end
		if matches(input) then
			trigger(true)
		end
	end))
	self._maid:Give(UserInputService.InputEnded:Connect(function(input)
		if not listening and matches(input) and self.Mode == "Hold" then
			trigger(false)
		end
	end))

	function self:Set(value, silent)
		self.Key = parseKey(value)
		render()
		if not silent then
			self.Changed:Fire(self.Value)
		end
	end
	function self:GetKey()
		return self.Key
	end
	function self:Serialize()
		return self.Key and self.Key.Name or "None"
	end
	function self:Deserialize(value)
		self:Set(value, true)
	end

	bindDisabled(self, title)
	local baseApply = self._applyDisabled
	self._applyDisabled = function(disabled)
		interactive:SetDisabled(disabled)
		baseApply(disabled)
	end
	reserveRight(block, right, 12)
	register(self)
	return self
end

--// Color picker \\--
function Controls.AddColorPicker(container, opts)
	local self = newControl("ColorPicker", opts, container)
	local row, right, block, title = makeRow(container, opts, 56)
	self.Row = row
	local default = opts.Default
	if typeof(default) == "string" then
		default = Util.FromHex(default)
	end
	self.Value = default or Color3.fromRGB(103, 80, 164)
	local hue, saturation, value = self.Value:ToHSV()

	local swatch = Frame({
		Name = "Swatch",
		Size = UDim2.fromOffset(40, 32),
		Position = UDim2.fromScale(1, 0.5),
		AnchorPoint = Vector2.new(1, 0.5),
		Radius = "Small",
		StrokeRole = "Outline",
		Parent = right,
	})
	swatch.BackgroundColor3 = self.Value
	swatch.BackgroundTransparency = 0
	right.Size = UDim2.new(0, 40, 1, 0)

	local popup, closePicker
	local open = false

	local function apply(silent)
		self.Value = Color3.fromHSV(hue, saturation, value)
		swatch.BackgroundColor3 = self.Value
		self:_emit(silent)
	end

	local function openPicker()
		if open or self.Disabled then
			return
		end
		Core.ClosePopups()
		open = true
		Core.RegisterPopup(closePicker)
		local overlay = Core.Overlay
		local scale = math.max(Util.Scale, 0.01)
		local width, height = 264, 288
		popup = Frame({
			Name = "ColorPicker",
			Canvas = true,
			Size = UDim2.fromOffset(width, 0),
			Role = "SurfaceContainerHigh",
			Radius = "Medium",
			ZIndex = 300,
			Parent = overlay,
		})
		local popStroke = Instance.new("UIStroke")
		popStroke.Thickness = 1
		Core.Bind(popStroke, "Color", "OutlineVariant")
		popStroke.Parent = popup

		local origin = overlay.AbsolutePosition
		local at = (swatch.AbsolutePosition - origin) / scale
		local overlaySize = overlay.AbsoluteSize / scale
		local x = math.clamp(at.X + 40 - width, 8, overlaySize.X - width - 8)
		local y = math.clamp(at.Y + 36, 8, overlaySize.Y - height - 8)
		popup.Position = UDim2.fromOffset(x, y)
		Padding(popup, 16, 16, 16, 16)

		local sv = Instance.new("ImageButton")
		sv.Selectable = false
		sv.Name = "SV"
		sv.AutoButtonColor = false
		sv.BorderSizePixel = 0
		sv.Size = UDim2.new(1, 0, 0, 144)
		sv.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
		sv.Image = ""
		sv.ZIndex = 301
		sv.Parent = popup
		Core.Corner(sv, "Small")
		local white = Instance.new("UIGradient")
		white.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.new(1, 1, 1))
		white.Transparency = NumberSequence.new(0, 1)
		white.Parent = sv
		local blackOverlay = Frame({ Size = UDim2.fromScale(1, 1), Role = Color3.new(0, 0, 0), ZIndex = 302, Parent = sv })
		Core.Corner(blackOverlay, "Small")
		local black = Instance.new("UIGradient")
		black.Rotation = 90
		black.Transparency = NumberSequence.new(1, 0)
		black.Parent = blackOverlay
		local cursor = Frame({
			Size = UDim2.fromOffset(16, 16),
			Role = Color3.new(1, 1, 1),
			Radius = "Full",
			StrokeRole = Color3.new(0, 0, 0),
			StrokeThickness = 2,
			AnchorPoint = Vector2.new(0.5, 0.5),
			ZIndex = 304,
			Parent = sv,
		})

		local hueBar = Instance.new("ImageButton")
		hueBar.Selectable = false
		hueBar.Name = "Hue"
		hueBar.AutoButtonColor = false
		hueBar.BorderSizePixel = 0
		hueBar.Size = UDim2.new(1, 0, 0, 16)
		hueBar.Position = UDim2.fromOffset(0, 156)
		hueBar.BackgroundColor3 = Color3.new(1, 1, 1)
		hueBar.Image = ""
		hueBar.ZIndex = 301
		hueBar.Parent = popup
		Core.Corner(hueBar, "Full")
		local keypoints = {}
		for i = 0, 6 do
			table.insert(keypoints, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(i / 6, 1, 1)))
		end
		local hueGradient = Instance.new("UIGradient")
		hueGradient.Color = ColorSequence.new(keypoints)
		hueGradient.Parent = hueBar
		local hueCursor = Frame({
			Size = UDim2.fromOffset(8, 24),
			Role = Color3.new(1, 1, 1),
			Radius = "Full",
			StrokeRole = Color3.new(0, 0, 0),
			StrokeThickness = 2,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(hue, 0.5),
			ZIndex = 303,
			Parent = hueBar,
		})

		local hexBox = Instance.new("TextBox")
		hexBox.Name = "Hex"
		hexBox.Size = UDim2.new(1, 0, 0, 40)
		hexBox.Position = UDim2.fromOffset(0, 184)
		hexBox.BorderSizePixel = 0
		hexBox.ClearTextOnFocus = false
		hexBox.TextSize = 14
		hexBox.ZIndex = 301
		hexBox.PlaceholderText = "#RRGGBB"
		Assets.Apply(hexBox, "Medium")
		Core.Bind(hexBox, "BackgroundColor3", "SurfaceContainerHighest")
		Core.Bind(hexBox, "TextColor3", "OnSurface")
		Core.Bind(hexBox, "PlaceholderColor3", "OnSurfaceVariant")
		hexBox.Parent = popup
		Core.Corner(hexBox, "Small")

		local function sync()
			sv.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
			cursor.Position = UDim2.fromScale(saturation, 1 - value)
			hueCursor.Position = UDim2.fromScale(hue, 0.5)
			hexBox.Text = Util.ToHex(Color3.fromHSV(hue, saturation, value))
		end
		sync()

		local draggingSV, draggingHue = false, false
		local function updateSV(input)
			local pos = Util.PointerPosition(input)
			saturation = math.clamp((pos.X - sv.AbsolutePosition.X) / math.max(sv.AbsoluteSize.X, 1), 0, 1)
			value = 1 - math.clamp((pos.Y - sv.AbsolutePosition.Y) / math.max(sv.AbsoluteSize.Y, 1), 0, 1)
			sync()
			apply(false)
		end
		local function updateHue(input)
			local pos = Util.PointerPosition(input)
			hue = math.clamp((pos.X - hueBar.AbsolutePosition.X) / math.max(hueBar.AbsoluteSize.X, 1), 0, 1)
			sync()
			apply(false)
		end
		sv.InputBegan:Connect(function(input)
			if Util.IsPointer(input) then
				draggingSV = true
				updateSV(input)
			end
		end)
		hueBar.InputBegan:Connect(function(input)
			if Util.IsPointer(input) then
				draggingHue = true
				updateHue(input)
			end
		end)
		local move = UserInputService.InputChanged:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
				if draggingSV then
					updateSV(input)
				elseif draggingHue then
					updateHue(input)
				end
			end
		end)
		local release = UserInputService.InputEnded:Connect(function(input)
			if Util.IsPointer(input) then
				draggingSV, draggingHue = false, false
			end
		end)
		popup.Destroying:Connect(function()
			move:Disconnect()
			release:Disconnect()
		end)
		hexBox.FocusLost:Connect(function()
			local parsed = Util.FromHex(hexBox.Text)
			if parsed then
				hue, saturation, value = parsed:ToHSV()
				sync()
				apply(false)
			else
				sync()
			end
		end)

		popup.Size = UDim2.fromOffset(width, 0)
		Util.Tween(popup, Util.Motion.Medium, { Size = UDim2.fromOffset(width, height) }, Enum.EasingStyle.Quint)
	end

	function closePicker()
		if not open then
			return
		end
		open = false
		Core.UnregisterPopup(closePicker)
		local p = popup
		popup = nil
		if p then
			local tween = Util.Tween(p, Util.Motion.Short, { Size = UDim2.fromOffset(p.Size.X.Offset, 0) }, Enum.EasingStyle.Quad)
			task.delay(tween and Util.Motion.Short or 0, function()
				p:Destroy()
			end)
		end
	end

	local interactive = Components.Interactive(swatch, {
		Radius = "Small",
		Tooltip = opts.Tooltip,
		ZIndex = 3,
		OnClick = function()
			if open then
				closePicker()
			elseif not Core.WasJustClosed(closePicker) then
				openPicker()
			end
		end,
	})

	self.Open = function()
		openPicker()
	end
	self.Close = function()
		closePicker()
	end

	function self:Set(color, silent)
		if typeof(color) == "string" then
			color = Util.FromHex(color)
		end
		if typeof(color) ~= "Color3" then
			return
		end
		hue, saturation, value = color:ToHSV()
		self.Value = color
		swatch.BackgroundColor3 = color
		self:_emit(silent)
	end
	function self:Serialize()
		return Util.ToHex(self.Value)
	end
	function self:Deserialize(v)
		self:Set(v, true)
	end

	self._maid:Give(closePicker)
	bindDisabled(self, title)
	local baseApply = self._applyDisabled
	self._applyDisabled = function(disabled)
		interactive:SetDisabled(disabled)
		baseApply(disabled)
		if disabled then
			closePicker()
		end
	end
	reserveRight(block, right, 12)
	register(self)
	return self
end

--// Attach all Add* methods to a container-like object \\--
function Controls.Attach(target, getContainer)
	local function wrap(name, fn)
		target[name] = function(self, opts)
			if typeof(opts) == "string" then
				opts = { Text = opts }
			end
			opts = opts or {}
			local control = fn(getContainer(self), opts)
			if self._track then
				self:_track(control, opts)
			end
			return control
		end
	end
	wrap("AddLabel", Controls.AddLabel)
	wrap("AddDivider", Controls.AddDivider)
	wrap("AddButton", Controls.AddButton)
	wrap("AddToggle", Controls.AddToggle)
	wrap("AddSlider", Controls.AddSlider)
	wrap("AddInput", Controls.AddInput)
	wrap("AddDropdown", Controls.AddDropdown)
	wrap("AddSegmented", Controls.AddSegmented)
	wrap("AddChips", Controls.AddChips)
	wrap("AddProgress", Controls.AddProgress)
	wrap("AddKeybind", Controls.AddKeybind)
	wrap("AddColorPicker", Controls.AddColorPicker)
	target.AddParagraph = function(self, opts)
		opts = opts or {}
		local control = Controls.AddLabel(getContainer(self), {
			Text = (opts.Title and ("<b>" .. opts.Title .. "</b>\n") or "") .. (opts.Content or opts.Text or ""),
			RichText = true,
			Role = "OnSurfaceVariant",
		})
		if self._track then
			self:_track(control, { Text = (opts.Title or "") .. " " .. (opts.Content or opts.Text or "") })
		end
		return control
	end
end

return Controls

end

__modules["Window"] = function()
-- Window: top bar, navigation (rail on desktop / bottom bar on narrow screens), pages, sections, profile card, search.

local Util = require("Util")
local Core = require("Core")
local Assets = require("Assets")
local Icons = require("Icons")
local Components = require("Components")
local Controls = require("Controls")

local UserInputService = game:GetService("UserInputService")

local Frame, Text, List, Padding = Components.Frame, Components.Text, Components.List, Components.Padding

local Window = {}
Window.__index = Window

local RAIL_WIDTH = 88
local TOPBAR_HEIGHT = 64
local COMPACT_BREAKPOINT = 560

--// Section \\--
local Section = {}
Section.__index = Section

Controls.Attach(Section, function(self)
	return self.Body
end)

function Section:_track(control, opts)
	local text = string.lower(table.concat({ opts.Text or "", opts.Description or "", opts.Flag or "" }, " "))
	table.insert(self._items, { control = control, text = text })
end

function Section:_filter(query)
	local anyVisible = false
	for _, item in self._items do
		local show = query == "" or item.text:find(query, 1, true) ~= nil
		item.control._filtered = not show
		item.control:_applyVisible()
		anyVisible = anyVisible or (show and not item.control._hidden)
	end
	if query == "" then
		self.Card.Visible = not self._hidden
		return true
	end
	self.Card.Visible = anyVisible and not self._hidden
	return anyVisible
end

function Section:SetTitle(title)
	self.Title.Text = title
end

function Section:SetVisible(visible)
	self._hidden = not visible
	self.Card.Visible = visible
end

function Section:Destroy()
	for _, item in self._items do
		item.control:Destroy()
	end
	self.Card:Destroy()
end

--// Tab (page) \\--
local Tab = {}
Tab.__index = Tab

function Tab:AddSection(opts)
	if typeof(opts) == "string" then
		opts = { Title = opts }
	end
	opts = opts or {}
	local section = setmetatable({ _items = {}, _hidden = false, Tab = self }, Section)

	local card = Frame({
		Name = opts.Title or "Section",
		Size = UDim2.new(1, 0, 0, 0),
		AutoSize = "Y",
		Role = opts.Elevated and "SurfaceContainerHigh" or "SurfaceContainer",
		Radius = "Large",
		Clip = true,
		Parent = self.Page,
	})
	card.LayoutOrder = opts.LayoutOrder or (#self.Sections + 1)
	section.Card = card
	List(card, 0)

	if opts.Title and opts.Title ~= "" then
		local header = Frame({ Name = "Header", Size = UDim2.new(1, 0, 0, 48), Parent = card })
		header.LayoutOrder = -1
		Padding(header, 0, 16, 0, 16)
		local left = 0
		if opts.Icon then
			Icons.Create(opts.Icon, {
				Size = 20,
				Color = "Primary",
				Position = UDim2.new(0, 0, 0.5, 0),
				AnchorPoint = Vector2.new(0, 0.5),
				Parent = header,
			})
			left = 30
		end
		section.Title = Text({
			Parent = header,
			Text = opts.Title,
			Style = "TitleSmall",
			Role = "Primary",
			Size = UDim2.new(1, -left, 1, 0),
			Position = UDim2.fromOffset(left, 0),
			Truncate = true,
		})
	else
		section.Title = { Text = "" }
	end

	local body = Frame({ Name = "Body", Size = UDim2.new(1, 0, 0, 0), AutoSize = "Y", Parent = card })
	body.LayoutOrder = 0
	List(body, 0)
	Padding(body, 0, 0, 8, 0)
	section.Body = body

	table.insert(self.Sections, section)
	if Core.Window then
		Core.Window:_applySearch()
	end
	return section
end

-- Adds controls straight onto the tab inside an automatic section (convenience).
function Tab:Section(title)
	return self:AddSection(title)
end

function Tab:SetBadge(value)
	self._badge = value
	self.Window:_refreshBadge(self)
end

function Tab:Select()
	self.Window:SelectTab(self)
end

function Tab:Destroy()
	self.Window:_removeTab(self)
end

--// Window \\--
function Window.new(library, opts)
	local self = setmetatable({}, Window)
	self.Library = library
	self.Options = opts
	self.Tabs = {}
	self.Selected = nil
	self._maid = Util.Maid.new()
	self._query = ""
	self.Opened = Util.Signal.new()
	self.Closed = Util.Signal.new()
	self.TabChanged = Util.Signal.new()
	self.Visible = false

	local root = library.Root
	local size = opts.Size or Vector2.new(780, 560)
	self.BaseSize = size

	local main = Frame({
		Name = "Window",
		Canvas = true,
		Size = UDim2.fromOffset(size.X, size.Y),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = "Surface",
		Radius = "XLarge",
		ZIndex = 10,
		Parent = root,
	})
	local outline = Instance.new("UIStroke")
	outline.Thickness = 1
	Core.Bind(outline, "Color", "OutlineVariant")
	outline.Parent = main
	self.Main = main

	-- Soft shadow made of stacked translucent frames (CanvasGroup clips children, so it lives on the root).
	local shadow = Frame({
		Name = "Shadow",
		Size = UDim2.new(0, size.X + 24, 0, size.Y + 24),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = Color3.new(0, 0, 0),
		Transparency = 0.8,
		Radius = 36,
		ZIndex = 9,
		Parent = root,
	})
	self.Shadow = shadow

	--// Top bar \\--
	local top = Frame({ Name = "TopBar", Size = UDim2.new(1, 0, 0, TOPBAR_HEIGHT), Role = "Surface", ZIndex = 12, Parent = main })
	self.TopBar = top
	local topContent = Frame({ Size = UDim2.fromScale(1, 1), ZIndex = 13, Parent = top })
	Padding(topContent, 0, 8, 0, 20)

	local left = Frame({ Name = "Left", Size = UDim2.new(0, 0, 1, 0), AutoSize = "X", ZIndex = 13, Parent = topContent })
	List(left, 12, Enum.FillDirection.Horizontal, nil, Enum.VerticalAlignment.Center)
	if opts.Icon then
		local logo = Icons.Create(opts.Icon, { Size = 28, Color = "Primary", Parent = left, ZIndex = 14 })
		logo.LayoutOrder = 0
	end
	local titleBlock = Frame({ Name = "Titles", Size = UDim2.new(0, 0, 1, 0), AutoSize = "X", ZIndex = 13, Parent = left })
	titleBlock.LayoutOrder = 1
	List(titleBlock, 0, nil, nil, Enum.VerticalAlignment.Center)
	self.TitleLabel = Text({
		Parent = titleBlock,
		Text = opts.Title or "Window",
		Style = "TitleLarge",
		Size = UDim2.fromOffset(0, 26),
		AutoSize = "X",
		ZIndex = 14,
	})
	self.SubtitleLabel = Text({
		Parent = titleBlock,
		Text = opts.Subtitle or "",
		Style = "BodySmall",
		Role = "OnSurfaceVariant",
		Size = UDim2.fromOffset(0, 16),
		AutoSize = "X",
		ZIndex = 14,
		LayoutOrder = 1,
	})
	self.SubtitleLabel.Visible = (opts.Subtitle or "") ~= ""

	local actions = Frame({
		Name = "Actions",
		Size = UDim2.new(0, 0, 1, 0),
		Position = UDim2.fromScale(1, 0),
		AnchorPoint = Vector2.new(1, 0),
		AutoSize = "X",
		ZIndex = 13,
		Parent = topContent,
	})
	List(actions, 4, Enum.FillDirection.Horizontal, nil, Enum.VerticalAlignment.Center)
	self.Actions = actions

	-- Search field (collapsed into an icon button on narrow windows)
	local searchHolder = Frame({
		Name = "Search",
		Size = UDim2.fromOffset(200, 40),
		Role = "SurfaceContainerHigh",
		Radius = "Full",
		ZIndex = 13,
		Parent = actions,
	})
	searchHolder.LayoutOrder = 0
	Icons.Create("search", { Size = 20, Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), Parent = searchHolder, ZIndex = 14 })
	local searchBox = Instance.new("TextBox")
	searchBox.Name = "Box"
	searchBox.BackgroundTransparency = 1
	searchBox.BorderSizePixel = 0
	searchBox.ClearTextOnFocus = false
	searchBox.PlaceholderText = "Search settings"
	searchBox.Text = ""
	searchBox.TextSize = 14
	searchBox.TextXAlignment = Enum.TextXAlignment.Left
	searchBox.Size = UDim2.new(1, -54, 1, 0)
	searchBox.Position = UDim2.fromOffset(42, 0)
	searchBox.ZIndex = 14
	Assets.Apply(searchBox, "Regular")
	Core.Bind(searchBox, "TextColor3", "OnSurface")
	Core.Bind(searchBox, "PlaceholderColor3", "OnSurfaceVariant")
	searchBox.Parent = searchHolder
	self.SearchHolder = searchHolder
	self.SearchBox = searchBox
	if opts.Search == false then
		searchHolder.Visible = false
	end
	self._maid:Give(searchBox:GetPropertyChangedSignal("Text"):Connect(function()
		self._query = string.lower(searchBox.Text)
		self:_applySearch()
	end))

	if opts.ThemeButton ~= false then
		local themeButton = Components.IconButton({
			Parent = actions,
			Icon = "dark_mode",
			Tooltip = "Toggle light / dark",
			Role = "OnSurfaceVariant",
			ZIndex = 14,
			LayoutOrder = 1,
			OnClick = function()
				local mode = Core.Mode == "Light" and "Dark" or "Light"
				Core.SetTheme({ Mode = mode }, true)
				self.Library.Changed:Fire("Theme", mode)
			end,
		})
		self.ThemeButton = themeButton
	end

	local minimize = Components.IconButton({
		Parent = actions,
		Icon = "minimize",
		Tooltip = "Hide (" .. Controls.KeyName(library.ToggleKey) .. ")",
		Role = "OnSurfaceVariant",
		ZIndex = 14,
		LayoutOrder = 2,
		OnClick = function()
			self:SetVisible(false)
		end,
	})
	self.MinimizeButton = minimize
	local closeButton = Components.IconButton({
		Parent = actions,
		Icon = "close",
		Tooltip = "Close",
		Role = "OnSurfaceVariant",
		ZIndex = 14,
		LayoutOrder = 3,
		OnClick = function()
			if opts.ConfirmClose then
				self.Library:Dialog({
					Title = "Close " .. (opts.Title or "window") .. "?",
					Content = "The interface will be destroyed. Your settings stay saved.",
					Icon = "power_settings_new",
					Buttons = {
						{ Text = "Cancel", Style = "Text" },
						{
							Text = "Close",
							Style = "Filled",
							Callback = function()
								self.Library:Unload()
							end,
						},
					},
				})
			else
				self.Library:Unload()
			end
		end,
	})
	self.CloseButton = closeButton

	self:_makeDraggable(top)

	local divider = Frame({
		Name = "Divider",
		Size = UDim2.new(1, 0, 0, 1),
		Position = UDim2.fromOffset(0, TOPBAR_HEIGHT),
		Role = "OutlineVariant",
		ZIndex = 12,
		Parent = main,
	})
	self.Divider = divider

	--// Body \\--
	local body = Frame({
		Name = "Body",
		Size = UDim2.new(1, 0, 1, -(TOPBAR_HEIGHT + 1)),
		Position = UDim2.fromOffset(0, TOPBAR_HEIGHT + 1),
		ZIndex = 11,
		Parent = main,
	})
	self.Body = body

	-- Navigation rail
	local rail = Frame({
		Name = "Rail",
		Size = UDim2.new(0, RAIL_WIDTH, 1, 0),
		Role = "Surface",
		ZIndex = 12,
		Parent = body,
	})
	self.Rail = rail
	local railScroll = Instance.new("ScrollingFrame")
	railScroll.Name = "Items"
	railScroll.BackgroundTransparency = 1
	railScroll.BorderSizePixel = 0
	railScroll.Size = UDim2.new(1, 0, 1, 0)
	railScroll.ScrollBarThickness = 0
	railScroll.CanvasSize = UDim2.new()
	railScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
	railScroll.ZIndex = 13
	railScroll.Parent = rail
	self.RailScroll = railScroll
	Padding(railScroll, 12, 0, 12, 0)
	self.RailLayout = List(railScroll, 12, Enum.FillDirection.Vertical, Enum.HorizontalAlignment.Center)

	-- Profile card (bottom of the rail)
	if opts.Profile ~= false then
		self:_buildProfile(rail, opts.Profile)
	end

	-- Pages
	local pages = Frame({
		Name = "Pages",
		Size = UDim2.new(1, -RAIL_WIDTH, 1, 0),
		Position = UDim2.fromOffset(RAIL_WIDTH, 0),
		Role = "Surface",
		ZIndex = 11,
		Clip = true,
		Parent = body,
	})
	self.Pages = pages

	-- Resize grip
	if opts.Resizable ~= false then
		self:_makeResizable(main)
	end

	self._maid:Give(main:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		self:_layoutResponsive()
	end))
	self:_layoutResponsive()
	main.Visible = false
	shadow.Visible = false
	return self
end

--// Profile card \\--
function Window:_buildProfile(rail, profileOpts)
	profileOpts = profileOpts or {}
	local Players = game:GetService("Players")
	local player = Players.LocalPlayer
	local card = Frame({
		Name = "Profile",
		Size = UDim2.new(1, -16, 0, 56),
		Position = UDim2.new(0.5, 0, 1, -8),
		AnchorPoint = Vector2.new(0.5, 1),
		Role = "SurfaceContainerHigh",
		Radius = "Large",
		ZIndex = 14,
		Parent = rail,
	})
	self.ProfileCard = card

	local avatar = Frame({
		Name = "AvatarFrame",
		Size = UDim2.fromOffset(40, 40),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = "PrimaryContainer",
		Radius = "Full",
		Canvas = true,
		ZIndex = 15,
		Parent = card,
	})
	local avatarImage = Instance.new("ImageLabel")
	avatarImage.Name = "Avatar"
	avatarImage.BackgroundTransparency = 1
	avatarImage.Size = UDim2.fromScale(1, 1)
	avatarImage.ZIndex = 16
	avatarImage.Parent = avatar
	local initial = Text({
		Parent = avatar,
		Text = "?",
		Style = "TitleMedium",
		Role = "OnPrimaryContainer",
		Size = UDim2.fromScale(1, 1),
		XAlign = Enum.TextXAlignment.Center,
		ZIndex = 15,
	})
	-- online status dot
	local dot = Frame({
		Name = "Status",
		Size = UDim2.fromOffset(12, 12),
		Position = UDim2.new(0.5, 14, 0.5, 14),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = "Success",
		Radius = "Full",
		StrokeRole = "SurfaceContainerHigh",
		StrokeThickness = 2,
		ZIndex = 17,
		Parent = card,
	})
	local _ = dot

	local displayName = profileOpts.DisplayName or (player and player.DisplayName) or "Guest"
	local userName = profileOpts.Username or (player and player.Name) or "guest"
	initial.Text = string.upper(string.sub(displayName, 1, 1))

	local userId = profileOpts.UserId or (player and player.UserId)
	if profileOpts.Image then
		Icons.Apply(avatarImage, profileOpts.Image)
		initial.Visible = false
	elseif userId and userId > 0 then
		task.spawn(function()
			local ok, content, ready = pcall(function()
				return Players:GetUserThumbnailAsync(userId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100)
			end)
			if ok and ready and content then
				avatarImage.Image = content
				initial.Visible = false
			end
		end)
	end

	-- Expanded card on wide layouts: name + username next to the avatar.
	local info = Frame({
		Name = "Info",
		Size = UDim2.new(1, -60, 1, 0),
		Position = UDim2.fromOffset(56, 0),
		ZIndex = 15,
		Parent = card,
	})
	List(info, 0, nil, nil, Enum.VerticalAlignment.Center)
	Text({ Parent = info, Text = displayName, Style = "LabelLarge", Size = UDim2.new(1, 0, 0, 18), Truncate = true, ZIndex = 16 })
	Text({
		Parent = info,
		Text = "@" .. userName,
		Style = "LabelSmall",
		Role = "OnSurfaceVariant",
		Size = UDim2.new(1, 0, 0, 14),
		Truncate = true,
		ZIndex = 16,
		LayoutOrder = 1,
	})
	info.Visible = false
	self.ProfileInfo = info
	self.ProfileAvatar = avatar
	self.ProfileTitle = displayName

	Components.Interactive(card, {
		Radius = "Large",
		StateRole = "OnSurface",
		Tooltip = displayName .. "  (@" .. userName .. ")",
		ZIndex = 14,
		OnClick = function()
			if profileOpts.OnClick then
				profileOpts.OnClick()
			end
		end,
	})
end

--// Layout (rail vs bottom bar) \\--
function Window:_layoutResponsive()
	local scale = math.max(Util.Scale, 0.01)
	local width = self.Main.AbsoluteSize.X / scale
	local compact = width < COMPACT_BREAKPOINT
	if self._compact == compact and self._railBuilt then
		return
	end
	self._compact = compact
	self._railBuilt = true

	if compact then
		self.Rail.Size = UDim2.new(1, 0, 0, 72)
		self.Rail.Position = UDim2.new(0, 0, 1, -72)
		self.Pages.Size = UDim2.new(1, 0, 1, -72)
		self.Pages.Position = UDim2.new()
		self.RailLayout.FillDirection = Enum.FillDirection.Horizontal
		self.RailLayout.VerticalAlignment = Enum.VerticalAlignment.Center
		self.RailLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		self.RailScroll.Size = UDim2.fromScale(1, 1)
		self.RailScroll.AutomaticCanvasSize = Enum.AutomaticSize.None
		self.RailScroll.CanvasSize = UDim2.new()
		if self.ProfileCard then
			self.ProfileCard.Visible = false
		end
		self.SearchHolder.Size = UDim2.fromOffset(40, 40)
		self.SearchBox.Visible = false
	else
		self.Rail.Size = UDim2.new(0, RAIL_WIDTH, 1, 0)
		self.Rail.Position = UDim2.new()
		self.Pages.Size = UDim2.new(1, -RAIL_WIDTH, 1, 0)
		self.Pages.Position = UDim2.fromOffset(RAIL_WIDTH, 0)
		self.RailLayout.FillDirection = Enum.FillDirection.Vertical
		self.RailLayout.VerticalAlignment = Enum.VerticalAlignment.Top
		self.RailLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		self.RailScroll.Size = UDim2.new(1, 0, 1, self.ProfileCard and -72 or 0)
		self.RailScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
		if self.ProfileCard then
			self.ProfileCard.Visible = true
		end
		self.SearchHolder.Size = UDim2.fromOffset(200, 40)
		self.SearchBox.Visible = true
	end
	for _, tab in self.Tabs do
		self:_styleNavItem(tab)
	end
end

--// Dragging / resizing \\--
function Window:_makeDraggable(handle)
	local dragging = false
	local startPointer, startPos
	local hit = Instance.new("TextButton")
	hit.Selectable = false
	hit.Name = "DragArea"
	hit.BackgroundTransparency = 1
	hit.Text = ""
	hit.AutoButtonColor = false
	hit.Size = UDim2.fromScale(1, 1)
	hit.ZIndex = 12
	hit.Parent = handle
	local main, shadow = self.Main, self.Shadow

	self._maid:Give(hit.InputBegan:Connect(function(input)
		if not Util.IsPointer(input) then
			return
		end
		dragging = true
		startPointer = Util.PointerPosition(input)
		startPos = main.AbsolutePosition + main.AbsoluteSize * 0.5
		Core.ClosePopups()
	end))
	self._maid:Give(UserInputService.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local scale = math.max(Util.Scale, 0.01)
			local delta = Util.PointerPosition(input) - startPointer
			local target = startPos + delta
			local rootSize = Core.Overlay.AbsoluteSize
			target = Vector2.new(math.clamp(target.X, 40, rootSize.X - 40), math.clamp(target.Y, 40, rootSize.Y - 40))
			local pos = UDim2.fromOffset((target.X - Core.Overlay.AbsolutePosition.X) / scale, (target.Y - Core.Overlay.AbsolutePosition.Y) / scale)
			main.Position = pos
			shadow.Position = pos
		end
	end))
	self._maid:Give(UserInputService.InputEnded:Connect(function(input)
		if dragging and Util.IsPointer(input) then
			dragging = false
		end
	end))
end

function Window:_makeResizable(main)
	local grip = Instance.new("TextButton")
	grip.Selectable = false
	grip.Name = "ResizeGrip"
	grip.BackgroundTransparency = 1
	grip.Text = ""
	grip.AutoButtonColor = false
	grip.Size = UDim2.fromOffset(28, 28)
	grip.Position = UDim2.fromScale(1, 1)
	grip.AnchorPoint = Vector2.new(1, 1)
	grip.ZIndex = 40
	grip.Parent = main
	local icon = Icons.Create("drag_handle", { Size = 14, Parent = grip, Position = UDim2.new(1, -6, 1, -6), AnchorPoint = Vector2.new(1, 1), ZIndex = 41 })
	icon.Rotation = -45
	icon.ImageTransparency = 0.5

	local resizing = false
	local startPointer, startSize
	local minimum = self.Options.MinSize or Vector2.new(420, 360)
	self._maid:Give(grip.InputBegan:Connect(function(input)
		if Util.IsPointer(input) then
			resizing = true
			startPointer = Util.PointerPosition(input)
			startSize = main.AbsoluteSize / math.max(Util.Scale, 0.01)
			Core.ClosePopups()
		end
	end))
	self._maid:Give(UserInputService.InputChanged:Connect(function(input)
		if resizing and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local scale = math.max(Util.Scale, 0.01)
			local delta = (Util.PointerPosition(input) - startPointer) / scale
			local overlay = Core.Overlay.AbsoluteSize / scale
			local width = math.clamp(startSize.X + delta.X * 2, minimum.X, overlay.X - 16)
			local height = math.clamp(startSize.Y + delta.Y * 2, minimum.Y, overlay.Y - 16)
			main.Size = UDim2.fromOffset(width, height)
			self.Shadow.Size = UDim2.fromOffset(width + 24, height + 24)
		end
	end))
	self._maid:Give(UserInputService.InputEnded:Connect(function(input)
		if resizing and Util.IsPointer(input) then
			resizing = false
		end
	end))
end

--// Navigation items \\--
function Window:_styleNavItem(tab)
	local nav = tab._nav
	if not nav then
		return
	end
	if self._compact then
		nav.holder.Size = UDim2.fromOffset(72, 64)
	else
		nav.holder.Size = UDim2.fromOffset(RAIL_WIDTH - 8, 64)
	end
end

function Window:_refreshBadge(tab)
	local nav = tab._nav
	if not nav then
		return
	end
	local badge = tab._badge
	if badge == nil or badge == false or badge == 0 or badge == "" then
		nav.badge.Visible = false
		return
	end
	nav.badge.Visible = true
	nav.badgeLabel.Text = typeof(badge) == "number" and tostring(math.min(badge, 99)) or tostring(badge)
end

function Window:_renderTabState(tab, animate)
	local nav = tab._nav
	local selected = self.Selected == tab
	local duration = animate and Util.Motion.Medium or 0
	Util.Tween(nav.pill, duration, {
		Size = selected and UDim2.fromOffset(56, 32) or UDim2.fromOffset(20, 32),
		BackgroundTransparency = selected and 0 or 1,
	}, Enum.EasingStyle.Quint)
	Core.Set(nav.label, "TextColor3", selected and "OnSurface" or "OnSurfaceVariant", duration)
	Core.Set(nav.icon, "ImageColor3", selected and "OnSecondaryContainer" or "OnSurfaceVariant", duration)
	Icons.Apply(nav.icon, tab.IconName, selected)
	nav.label.FontFace = Assets.Font(selected and "SemiBold" or "Medium")
end

function Window:AddTab(opts)
	if typeof(opts) == "string" then
		opts = { Name = opts }
	end
	opts = opts or {}
	local tab = setmetatable({
		Window = self,
		Name = opts.Name or ("Tab " .. (#self.Tabs + 1)),
		IconName = opts.Icon or "widgets",
		Sections = {},
		_badge = opts.Badge,
	}, Tab)

	local holder = Frame({
		Name = tab.Name,
		Size = UDim2.fromOffset(RAIL_WIDTH - 8, 64),
		ZIndex = 14,
		Parent = self.RailScroll,
	})
	holder.LayoutOrder = #self.Tabs + 1
	local pill = Frame({
		Name = "Pill",
		Size = UDim2.fromOffset(20, 32),
		Position = UDim2.new(0.5, 0, 0, 4),
		AnchorPoint = Vector2.new(0.5, 0),
		Role = "SecondaryContainer",
		Transparency = 1,
		Radius = "Full",
		ZIndex = 15,
		Parent = holder,
	})
	local icon = Icons.Create(tab.IconName, {
		Size = 24,
		Color = "OnSurfaceVariant",
		Position = UDim2.new(0.5, 0, 0, 8),
		AnchorPoint = Vector2.new(0.5, 0),
		Parent = holder,
		ZIndex = 17,
	})
	local label = Text({
		Parent = holder,
		Text = tab.Name,
		Style = "LabelMedium",
		Role = "OnSurfaceVariant",
		Size = UDim2.new(1, 0, 0, 16),
		Position = UDim2.new(0, 0, 0, 40),
		XAlign = Enum.TextXAlignment.Center,
		Truncate = true,
		ZIndex = 16,
	})
	local badge = Frame({
		Name = "Badge",
		Size = UDim2.fromOffset(16, 16),
		Position = UDim2.new(0.5, 10, 0, 4),
		AnchorPoint = Vector2.new(0, 0),
		Role = "Error",
		Radius = "Full",
		ZIndex = 19,
		Parent = holder,
	})
	badge.Visible = false
	local badgeLabel = Text({
		Parent = badge,
		Style = "LabelSmall",
		Role = "OnError",
		Size = UDim2.fromScale(1, 1),
		XAlign = Enum.TextXAlignment.Center,
		ZIndex = 20,
	})
	badgeLabel.TextSize = 10
	tab._nav = { holder = holder, pill = pill, icon = icon, label = label, badge = badge, badgeLabel = badgeLabel }

	Components.Interactive(holder, {
		Radius = "Large",
		StateRole = "OnSurface",
		Tooltip = opts.Tooltip,
		ZIndex = 14,
		OnClick = function()
			self:SelectTab(tab)
		end,
	})

	-- Page
	local page = Instance.new("ScrollingFrame")
	page.Name = tab.Name
	page.BackgroundTransparency = 1
	page.BorderSizePixel = 0
	page.Size = UDim2.fromScale(1, 1)
	page.CanvasSize = UDim2.new()
	page.AutomaticCanvasSize = Enum.AutomaticSize.Y
	page.ScrollBarThickness = 4
	page.ScrollingDirection = Enum.ScrollingDirection.Y
	page.ZIndex = 12
	page.Visible = false
	Core.Bind(page, "ScrollBarImageColor3", "Outline")
	page.Parent = self.Pages
	Padding(page, 16, 16, 16, 16)
	List(page, 12)
	tab.Page = page

	table.insert(self.Tabs, tab)
	self:_styleNavItem(tab)
	self:_refreshBadge(tab)
	self:_renderTabState(tab, false)

	if #self.Tabs == 1 or opts.Default then
		self:SelectTab(tab, true)
	end
	return tab
end

function Window:SelectTab(tab, instant)
	if typeof(tab) == "string" then
		for _, candidate in self.Tabs do
			if candidate.Name == tab then
				tab = candidate
				break
			end
		end
	end
	if typeof(tab) ~= "table" or self.Selected == tab then
		return
	end
	Core.ClosePopups()
	local previous = self.Selected
	self.Selected = tab
	for _, candidate in self.Tabs do
		self:_renderTabState(candidate, not instant)
	end

	if previous and not instant and Util.AnimationsEnabled then
		local page = tab.Page
		page.Visible = true
		page.Position = UDim2.fromOffset(0, 14)
		previous.Page.Visible = false
		-- fade content in by sliding up; ScrollingFrame has no group transparency
		Util.Tween(page, Util.Motion.Medium, { Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quint)
	else
		if previous then
			previous.Page.Visible = false
		end
		tab.Page.Visible = true
		tab.Page.Position = UDim2.new()
	end
	self:_applySearch()
	self.TabChanged:Fire(tab.Name)
end

function Window:_removeTab(tab)
	local index = table.find(self.Tabs, tab)
	if not index then
		return
	end
	table.remove(self.Tabs, index)
	for _, section in tab.Sections do
		section:Destroy()
	end
	tab._nav.holder:Destroy()
	tab.Page:Destroy()
	if self.Selected == tab then
		self.Selected = nil
		if self.Tabs[1] then
			self:SelectTab(self.Tabs[1], true)
		end
	end
end

function Window:GetTab(name)
	for _, tab in self.Tabs do
		if tab.Name == name then
			return tab
		end
	end
	return nil
end

--// Search \\--
function Window:_applySearch()
	local tab = self.Selected
	if not tab then
		return
	end
	local anyVisible = false
	for _, section in tab.Sections do
		anyVisible = section:_filter(self._query) or anyVisible
	end
	if self._emptyState then
		self._emptyState.Visible = self._query ~= "" and not anyVisible
	elseif self._query ~= "" and not anyVisible then
		local empty = Frame({ Name = "Empty", Size = UDim2.new(1, 0, 0, 160), ZIndex = 12, Parent = self.Pages })
		Icons.Create("search", { Size = 40, Position = UDim2.new(0.5, 0, 0.5, -20), AnchorPoint = Vector2.new(0.5, 0.5), Parent = empty, ZIndex = 13 })
		Text({
			Parent = empty,
			Text = "No settings match your search",
			Style = "BodyMedium",
			Role = "OnSurfaceVariant",
			Position = UDim2.new(0, 0, 0.5, 18),
			Size = UDim2.new(1, 0, 0, 20),
			XAlign = Enum.TextXAlignment.Center,
			ZIndex = 13,
		})
		self._emptyState = empty
	end
end

function Window:ClearSearch()
	self.SearchBox.Text = ""
end

--// Visibility \\--
function Window:SetVisible(visible)
	visible = visible and true or false
	if visible == self.Visible then
		return
	end
	self.Visible = visible
	local main, shadow = self.Main, self.Shadow
	Core.ClosePopups()
	if visible then
		main.Visible = true
		shadow.Visible = true
		if Util.AnimationsEnabled then
			self._scale = self._scale or Instance.new("UIScale")
			local uiScale = self._scale
			uiScale.Parent = main
			uiScale.Scale = 0.92
			main.GroupTransparency = 1
			Util.Tween(uiScale, Util.Motion.Medium, { Scale = 1 }, Enum.EasingStyle.Quint)
			Util.Tween(main, Util.Motion.Medium, { GroupTransparency = 0 }, Enum.EasingStyle.Quad)
			shadow.BackgroundTransparency = 1
			Util.Tween(shadow, Util.Motion.Medium, { BackgroundTransparency = 0.8 }, Enum.EasingStyle.Quad)
		else
			main.GroupTransparency = 0
		end
		self.Opened:Fire()
	else
		if Util.AnimationsEnabled then
			self._scale = self._scale or Instance.new("UIScale")
			local uiScale = self._scale
			uiScale.Parent = main
			Util.Tween(uiScale, Util.Motion.Short, { Scale = 0.94 }, Enum.EasingStyle.Quad)
			Util.Tween(main, Util.Motion.Short, { GroupTransparency = 1 }, Enum.EasingStyle.Quad)
			Util.Tween(shadow, Util.Motion.Short, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad)
			task.delay(Util.Motion.Short, function()
				if not self.Visible then
					main.Visible = false
					shadow.Visible = false
				end
			end)
		else
			main.Visible = false
			shadow.Visible = false
		end
		self.Closed:Fire()
	end
end

function Window:Toggle()
	self:SetVisible(not self.Visible)
end

function Window:SetTitle(title, subtitle)
	self.TitleLabel.Text = title
	if subtitle ~= nil then
		self.SubtitleLabel.Text = subtitle
		self.SubtitleLabel.Visible = subtitle ~= ""
	end
end

function Window:Destroy()
	self._maid:Clean()
	self.Main:Destroy()
	self.Shadow:Destroy()
end

return Window

end

__modules["Library"] = function()
-- Public entry point of Zaridium UI (Material 3 edition).

local Util = require("Util")
local Color = require("Color")
local Core = require("Core")
local Assets = require("Assets")
local Icons = require("Icons")
local Components = require("Components")
local Controls = require("Controls")
local Window = require("Window")

local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local CoreGui = game:GetService("CoreGui")
local TweenService = game:GetService("TweenService")

local Frame, Text, List, Padding = Components.Frame, Components.Text, Components.List, Components.Padding

local VERSION = "1.0.0"

local Library = {
	Version = VERSION,
	Flags = Core.Flags,
	Options = Core.Options,
	Util = Util,
	Color = Color,
	Icons = Icons,
	Controls = Controls,
	Changed = Util.Signal.new(),
	Unloading = Util.Signal.new(),
	ToggleKey = Enum.KeyCode.RightControl,
	Unloaded = false,
	Window = nil,
	Root = nil,
	UIScale = nil :: UIScale?,
}

-- Executor globals are optional: capture them as `any` and check with typeof() before calling.
local writefile: any, readfile: any, isfile: any, isfolder: any, makefolder: any, listfiles: any, delfile: any =
	writefile, readfile, isfile, isfolder, makefolder, listfiles, delfile
local gethui: any, getgenv: any = gethui, getgenv

local initialised = false
local notifications = {}
local notificationHolder = nil
local maid = Util.Maid.new()
local dialogLayer = nil

local function protectedParent()
	local ok, parent = pcall(function()
		if typeof(gethui) == "function" then
			return gethui()
		end
		return nil
	end)
	if ok and parent then
		return parent
	end
	local okCore = pcall(function()
		return CoreGui.Name
	end)
	if okCore then
		return CoreGui
	end
	local player = Players.LocalPlayer
	return player and player:FindFirstChildOfClass("PlayerGui") or nil
end

-- Reads executor globals defensively (they may be nil).
local function executorFn(name)
	local env = typeof(getgenv) == "function" and getgenv() or nil
	local value = env and env[name] or nil
	return typeof(value) == "function" and value or nil
end

--// Setup \\--
-- config: Title, Subtitle, Icon, Theme{Mode,Preset,Seed,Overrides}, Size (Vector2), Scale (number), ToggleKey, AutoShow,
--         Profile (false | {DisplayName,Username,UserId,Image,OnClick}), Offline, AssetBaseUrl, CacheFolder, Font (Font),
--         RoundedFont, Animations, Ripple, AnimationSpeed, Resizable, Search, ThemeButton, ConfirmClose, Name, MinSize
function Library:CreateWindow(config)
	config = config or {}
	if Library.Window then
		warn("[ZaridiumUI] a window already exists; destroying the previous one")
		Library:Unload()
	end
	Library.Unloaded = false

	Util.AnimationsEnabled = config.Animations ~= false
	Util.RippleEnabled = config.Ripple ~= false
	Util.Speed = config.AnimationSpeed or 1

	Assets.Init({
		AssetBaseUrl = config.AssetBaseUrl,
		CacheFolder = config.CacheFolder,
		Version = VERSION,
		RoundedFont = config.RoundedFont,
		Font = config.Font,
		AtlasImage = config.AtlasImage,
		Offline = config.Offline,
	})

	local theme = config.Theme or {}
	Core.Mode = Color.Schemes[theme.Mode] and theme.Mode or "Dark"
	Core.Overrides = theme.Overrides or {}
	local preset = theme.Preset and Color.FindPreset(theme.Preset)
	if preset then
		Core.Preset = preset.Name
		Core.Seed = Color3.fromHex(preset.Seed)
	end
	if theme.Seed then
		local seed = typeof(theme.Seed) == "string" and Util.FromHex(theme.Seed) or theme.Seed
		if typeof(seed) == "Color3" then
			Core.Seed = seed
			Core.Preset = "Custom"
		end
	end
	if config.CornerScale then
		Core.CornerScale = math.clamp(config.CornerScale, 0, 2)
	end
	Core.Roles = Core.BuildRoles()

	Library.ToggleKey = config.ToggleKey or Enum.KeyCode.RightControl

	local gui = Instance.new("ScreenGui")
	gui.Name = config.Name or ("ZaridiumUI_" .. string.sub(HttpService:GenerateGUID(false), 1, 8))
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.DisplayOrder = 10000
	gui.ScreenInsets = Enum.ScreenInsets.None
	local protect = executorFn("protectgui") or executorFn("protect_gui")
	if protect then
		pcall(protect, gui)
	end
	gui.Parent = protectedParent()
	Core.ScreenGui = gui

	local root = Instance.new("Frame")
	root.Name = "Root"
	root.BackgroundTransparency = 1
	root.Size = UDim2.fromScale(1, 1)
	root.ZIndex = 1
	root.Parent = gui
	local uiScale = Instance.new("UIScale")
	uiScale.Parent = root
	Library.Root = root
	Library.UIScale = uiScale
	Core.Overlay = root

	local function updateScale()
		if config.Scale then
			uiScale.Scale = config.Scale
		else
			local viewport = gui.AbsoluteSize
			local base = math.min(viewport.X / 1280, viewport.Y / 720)
			uiScale.Scale = math.clamp(base, 0.6, 1.25)
		end
		Util.Scale = uiScale.Scale
		-- UIScale scales around the top-left corner, so a full-size root would overflow the screen.
		root.Size = UDim2.fromScale(1 / uiScale.Scale, 1 / uiScale.Scale)
	end
	updateScale()
	maid:Give(gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateScale))

	-- Click-away layer that closes popups
	local blocker = Instance.new("TextButton")
	blocker.Selectable = false
	blocker.Name = "PopupBlocker"
	blocker.BackgroundTransparency = 1
	blocker.Text = ""
	blocker.AutoButtonColor = false
	blocker.Size = UDim2.fromScale(1, 1)
	blocker.ZIndex = 250
	blocker.Visible = false
	blocker.Parent = root
	maid:Give(blocker.Activated:Connect(function()
		Core.ClosePopups(nil, true)
	end))
	local registerPopup, unregisterPopup = Core.RegisterPopup, Core.UnregisterPopup
	function Core.RegisterPopup(close)
		registerPopup(close)
		blocker.Visible = true
	end
	function Core.UnregisterPopup(close)
		unregisterPopup(close)
		blocker.Visible = #Core.Popups > 0
	end

	local _, tooltipConnection = Components.InstallTooltips(root)
	maid:Give(tooltipConnection)

	-- Notification stack (top right)
	notificationHolder = Frame({
		Name = "Notifications",
		Size = UDim2.new(0, 360, 1, -32),
		Position = UDim2.new(1, -16, 0, 16),
		AnchorPoint = Vector2.new(1, 0),
		ZIndex = 500,
		Parent = root,
	})
	List(notificationHolder, 8, nil, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Top)

	dialogLayer = Frame({ Name = "Dialogs", Size = UDim2.fromScale(1, 1), ZIndex = 600, Parent = root })
	dialogLayer.Visible = false

	local profile = config.Profile
	local window = Window.new(Library, {
		Title = config.Title,
		Subtitle = config.Subtitle,
		Icon = config.Icon,
		Size = config.Size,
		MinSize = config.MinSize,
		Profile = profile,
		Resizable = config.Resizable,
		Search = config.Search,
		ThemeButton = config.ThemeButton,
		ConfirmClose = config.ConfirmClose,
	})
	Library.Window = window
	Core.Window = window

	local env = typeof(getgenv) == "function" and getgenv() or nil
	if env then
		env.ZaridiumUI = Library
	end

	-- Global toggle key + Escape closes popups
	maid:Give(UserInputService.InputBegan:Connect(function(input, processed)
		if Library.Unloaded or Core.Listening then
			return
		end
		if input.KeyCode == Library.ToggleKey and not UserInputService:GetFocusedTextBox() then
			window:Toggle()
		elseif input.KeyCode == Enum.KeyCode.Escape and #Core.Popups > 0 and not processed then
			Core.ClosePopups()
		end
	end))

	initialised = true
	if config.AutoShow ~= false then
		task.defer(function()
			if not Library.Unloaded then
				window:SetVisible(true)
			end
		end)
	end
	return window
end

--// Notifications \\--
-- opts: Title, Content, Duration (seconds, 0 = sticky), Type ("Info"|"Success"|"Warning"|"Error"), Icon, Action = { Text, Callback }
function Library:Notify(opts)
	if not initialised or Library.Unloaded then
		return nil
	end
	if typeof(opts) == "string" then
		opts = { Content = opts }
	end
	local kind = opts.Type or "Info"
	local palette = {
		Info = { bg = "SecondaryContainer", fg = "OnSecondaryContainer", icon = "info" },
		Success = { bg = "SuccessContainer", fg = "OnSuccessContainer", icon = "check_circle" },
		Warning = { bg = "WarningContainer", fg = "OnWarningContainer", icon = "warning" },
		Error = { bg = "ErrorContainer", fg = "OnErrorContainer", icon = "error" },
	}
	local style = palette[kind] or palette.Info

	local slot = Frame({
		Name = "Slot",
		Size = UDim2.new(1, 0, 0, 0),
		AutoSize = "Y",
		Parent = notificationHolder,
	})
	slot.LayoutOrder = os.clock() * 1000
	local card = Frame({
		Name = "Notification",
		Canvas = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutoSize = "Y",
		Position = UDim2.fromOffset(380, 0),
		Role = style.bg,
		Radius = "Large",
		ZIndex = 501,
		Parent = slot,
	})
	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 1
	Core.Bind(stroke, "Color", "OutlineVariant")
	stroke.Parent = card
	List(card, 0)
	local inner = Frame({ Size = UDim2.new(1, 0, 0, 0), AutoSize = "Y", ZIndex = 502, Parent = card })
	Padding(inner, 14, 14, 14, 14)
	local icon = Icons.Create(opts.Icon or style.icon, {
		Size = 24,
		Color = style.fg,
		Position = UDim2.fromOffset(0, 0),
		Parent = inner,
		ZIndex = 503,
	})
	local textBlock = Frame({
		Size = UDim2.new(1, -66, 0, 0),
		AutoSize = "Y",
		Position = UDim2.fromOffset(36, 0),
		ZIndex = 503,
		Parent = inner,
	})
	List(textBlock, 2)
	if opts.Title then
		Text({
			Parent = textBlock,
			Text = opts.Title,
			Style = "TitleSmall",
			Role = style.fg,
			Size = UDim2.new(1, 0, 0, 20),
			Wrap = true,
			AutoSize = "Y",
			ZIndex = 504,
		})
	end
	if opts.Content then
		local body = Text({
			Parent = textBlock,
			Text = opts.Content,
			Style = "BodyMedium",
			Role = style.fg,
			Size = UDim2.new(1, 0, 0, 0),
			Wrap = true,
			AutoSize = "Y",
			ZIndex = 504,
			LayoutOrder = 1,
		})
		body.TextTransparency = 0.12
	end
	if opts.Action then
		local actionButton = Frame({
			Name = "Action",
			Size = UDim2.fromOffset(0, 32),
			AutoSize = "X",
			Radius = "Full",
			ZIndex = 504,
			Parent = textBlock,
		})
		actionButton.LayoutOrder = 2
		Padding(actionButton, 0, 8, 0, 8)
		Text({
			Parent = actionButton,
			Text = opts.Action.Text or "Action",
			Style = "LabelLarge",
			Role = style.fg,
			Size = UDim2.fromOffset(0, 32),
			AutoSize = "X",
			ZIndex = 505,
		})
		Components.Interactive(actionButton, {
			Radius = "Full",
			StateRole = style.fg,
			ZIndex = 504,
			OnClick = function()
				if opts.Action.Callback then
					task.spawn(opts.Action.Callback)
				end
			end,
		})
	end
	local close
	Components.IconButton({
		Parent = inner,
		Icon = "close",
		Size = 28,
		Role = style.fg,
		Position = UDim2.new(1, 0, 0, -2),
		AnchorPoint = Vector2.new(1, 0),
		ZIndex = 504,
		OnClick = function()
			close()
		end,
	})
	local _ = icon

	local duration = opts.Duration
	if duration == nil then
		duration = 5
	end
	local progress
	if duration > 0 then
		local bar = Frame({
			Name = "Timer",
			Size = UDim2.new(1, 0, 0, 3),
			ZIndex = 506,
			Parent = card,
		})
		bar.LayoutOrder = 1
		progress = Frame({ Size = UDim2.fromScale(1, 1), Role = style.fg, Transparency = 0.5, ZIndex = 507, Parent = bar })
	end

	local closed = false
	function close()
		if closed then
			return
		end
		closed = true
		local tween = Util.Tween(card, Util.Motion.Medium, { Position = UDim2.fromOffset(380, 0) }, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
		task.delay(tween and Util.Motion.Medium or 0, function()
			local index = table.find(notifications, slot)
			if index then
				table.remove(notifications, index)
			end
			slot:Destroy()
		end)
	end

	table.insert(notifications, slot)
	while #notifications > 6 do
		local oldest = table.remove(notifications, 1)
		if oldest then
			oldest:Destroy()
		end
	end

	task.defer(function()
		Util.Tween(card, Util.Motion.Medium, { Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quint)
	end)
	if progress then
		local tween = TweenService:Create(progress, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Size = UDim2.fromScale(0, 1) })
		tween:Play()
		task.delay(duration, close)
	end
	return { Close = close }
end

--// Dialogs \\--
-- opts: Title, Content, Icon, Buttons = { { Text, Style ("Filled"|"Tonal"|"Text"|"Danger"), Callback }, ... }
function Library:Dialog(opts)
	if not initialised or Library.Unloaded then
		return nil
	end
	opts = opts or {}
	Core.ClosePopups()
	local scrim = Frame({
		Name = "Scrim",
		Size = UDim2.fromScale(1, 1),
		Role = Color3.new(0, 0, 0),
		Transparency = 1,
		ZIndex = 601,
		Parent = dialogLayer,
	})
	dialogLayer.Visible = true
	Util.Tween(scrim, Util.Motion.Medium, { BackgroundTransparency = 0.5 }, Enum.EasingStyle.Quad)

	local sink = Instance.new("TextButton")
	sink.Selectable = false
	sink.BackgroundTransparency = 1
	sink.Text = ""
	sink.AutoButtonColor = false
	sink.Size = UDim2.fromScale(1, 1)
	sink.ZIndex = 601
	sink.Parent = scrim

	local card = Frame({
		Name = "Dialog",
		Canvas = true,
		Size = UDim2.fromOffset(360, 0),
		AutoSize = "Y",
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Role = "SurfaceContainerHigh",
		Radius = "XLarge",
		ZIndex = 602,
		Parent = scrim,
	})
	local cardScale = Instance.new("UIScale")
	cardScale.Scale = 0.9
	cardScale.Parent = card
	card.GroupTransparency = 1
	Util.Tween(cardScale, Util.Motion.Medium, { Scale = 1 }, Enum.EasingStyle.Quint)
	Util.Tween(card, Util.Motion.Medium, { GroupTransparency = 0 }, Enum.EasingStyle.Quad)

	local body = Frame({ Size = UDim2.new(1, 0, 0, 0), AutoSize = "Y", ZIndex = 603, Parent = card })
	Padding(body, 24, 24, 24, 24)
	List(body, 16, nil, Enum.HorizontalAlignment.Left)
	if opts.Icon then
		local icon = Icons.Create(opts.Icon, { Size = 28, Color = "Secondary", Parent = body, ZIndex = 604 })
		icon.LayoutOrder = 0
	end
	local title = Text({
		Parent = body,
		Text = opts.Title or "Dialog",
		Style = "HeadlineSmall",
		Size = UDim2.new(1, 0, 0, 0),
		Wrap = true,
		AutoSize = "Y",
		ZIndex = 604,
		LayoutOrder = 1,
	})
	title.TextSize = 22
	if opts.Content then
		Text({
			Parent = body,
			Text = opts.Content,
			Style = "BodyMedium",
			Role = "OnSurfaceVariant",
			Size = UDim2.new(1, 0, 0, 0),
			Wrap = true,
			AutoSize = "Y",
			ZIndex = 604,
			LayoutOrder = 2,
		})
	end

	local function close()
		local tween = Util.Tween(card, Util.Motion.Short, { GroupTransparency = 1 }, Enum.EasingStyle.Quad)
		Util.Tween(cardScale, Util.Motion.Short, { Scale = 0.94 }, Enum.EasingStyle.Quad)
		Util.Tween(scrim, Util.Motion.Short, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad)
		task.delay(tween and Util.Motion.Short or 0, function()
			scrim:Destroy()
			if #dialogLayer:GetChildren() == 0 then
				dialogLayer.Visible = false
			end
		end)
	end

	local buttons = opts.Buttons or { { Text = "OK", Style = "Text" } }
	local row = Frame({ Size = UDim2.new(1, 0, 0, 40), ZIndex = 604, Parent = body })
	row.LayoutOrder = 3
	List(row, 8, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Center)
	for index, definition in buttons do
		local style = definition.Style or "Text"
		local background, content
		if style == "Filled" then
			background, content = "Primary", "OnPrimary"
		elseif style == "Danger" then
			background, content = "Error", "OnError"
		elseif style == "Tonal" then
			background, content = "SecondaryContainer", "OnSecondaryContainer"
		else
			background, content = nil, "Primary"
		end
		local button = Frame({
			Name = definition.Text or "Button",
			Size = UDim2.fromOffset(0, 40),
			AutoSize = "X",
			Role = background,
			Radius = "Full",
			ZIndex = 605,
			Parent = row,
		})
		button.LayoutOrder = index
		Padding(button, 0, 24, 0, 24)
		Text({
			Parent = button,
			Text = definition.Text or "OK",
			Style = "LabelLarge",
			Role = content,
			Size = UDim2.fromOffset(0, 40),
			AutoSize = "X",
			ZIndex = 606,
		})
		Components.Interactive(button, {
			Radius = "Full",
			StateRole = content,
			ZIndex = 605,
			OnClick = function()
				close()
				if definition.Callback then
					task.spawn(definition.Callback)
				end
			end,
		})
	end
	return { Close = close }
end

--// Theme API \\--
function Library:SetTheme(options, animate)
	Core.SetTheme(options, animate)
	Library.Changed:Fire("Theme", Core.Mode, Core.Preset)
end

function Library:GetTheme()
	return { Mode = Core.Mode, Preset = Core.Preset, Seed = Core.Seed, Overrides = Core.Overrides }
end

function Library:GetColor(role)
	return Core.Roles[role]
end

function Library:SetAnimations(enabled, speed)
	Util.AnimationsEnabled = enabled ~= false
	if speed then
		Util.Speed = math.clamp(speed, 0.25, 4)
	end
end

function Library:SetRipple(enabled)
	Util.RippleEnabled = enabled ~= false
end

function Library:SetCornerScale(scale)
	Core.SetCornerScale(scale)
end

function Library:SetRoundedFont(enabled)
	Assets.SetRounded(enabled)
end

function Library:SetScale(scale)
	if Library.UIScale and Library.Root then
		Library.UIScale.Scale = math.clamp(scale, 0.5, 2)
		Util.Scale = Library.UIScale.Scale
		Library.Root.Size = UDim2.fromScale(1 / Util.Scale, 1 / Util.Scale)
	end
end

function Library:SetToggleKey(key)
	Library.ToggleKey = key
end

function Library:Toggle(visible)
	if Library.Window then
		if visible == nil then
			Library.Window:Toggle()
		else
			Library.Window:SetVisible(visible)
		end
	end
end

--// Config management \\--
local Config = {
	Folder = "ZaridiumUI",
	IgnoredFlags = {},
}
Library.Config = Config

local function canFiles()
	return typeof(writefile) == "function" and typeof(readfile) == "function" and typeof(isfile) == "function"
end

local function configPath(name)
	return Config.Folder .. "/configs/" .. name .. ".json"
end

function Config:SetFolder(folder)
	Config.Folder = folder
end

function Config:Ignore(flags)
	for _, flag in flags do
		Config.IgnoredFlags[flag] = true
	end
end

function Config:Encode()
	local data = { version = 1, flags = {} }
	for flag, control in Core.Options do
		if not Config.IgnoredFlags[flag] then
			local value = control:Serialize()
			if value ~= nil then
				data.flags[flag] = value
			end
		end
	end
	return HttpService:JSONEncode(data)
end

function Config:Decode(json)
	local ok, data = pcall(function()
		return HttpService:JSONDecode(json)
	end)
	if not ok or typeof(data) ~= "table" or typeof(data.flags) ~= "table" then
		return false, "invalid config data"
	end
	for flag, value in data.flags do
		local control = Core.Options[flag]
		if control and not Config.IgnoredFlags[flag] then
			pcall(function()
				control:Deserialize(value, false)
			end)
		end
	end
	return true
end

function Config:Save(name)
	if not canFiles() then
		return false, "executor has no file API"
	end
	if typeof(name) ~= "string" or name:gsub("%s", "") == "" then
		return false, "config name is empty"
	end
	pcall(function()
		if typeof(makefolder) == "function" then
			if not isfolder(Config.Folder) then
				makefolder(Config.Folder)
			end
			if not isfolder(Config.Folder .. "/configs") then
				makefolder(Config.Folder .. "/configs")
			end
		end
	end)
	local ok, err = pcall(writefile, configPath(name), Config:Encode())
	if not ok then
		return false, tostring(err)
	end
	return true
end

function Config:Load(name)
	if not canFiles() then
		return false, "executor has no file API"
	end
	local path = configPath(name)
	if not isfile(path) then
		return false, "config does not exist"
	end
	local ok, content = pcall(readfile, path)
	if not ok then
		return false, tostring(content)
	end
	return Config:Decode(content)
end

function Config:Delete(name)
	if typeof(delfile) == "function" and isfile(configPath(name)) then
		pcall(delfile, configPath(name))
		return true
	end
	return false
end

function Config:List()
	local names = {}
	if typeof(listfiles) == "function" and typeof(isfolder) == "function" and isfolder(Config.Folder .. "/configs") then
		local ok, files = pcall(listfiles, Config.Folder .. "/configs")
		if ok then
			for _, file in files do
				local name = tostring(file):match("([^/\\]+)%.json$")
				if name and name ~= "autoload" then
					table.insert(names, name)
				end
			end
		end
	end
	table.sort(names)
	return names
end

function Config:SetAutoload(name)
	if not canFiles() then
		return false
	end
	pcall(writefile, Config.Folder .. "/configs/autoload.txt", name or "")
	return true
end

function Config:GetAutoload()
	local path = Config.Folder .. "/configs/autoload.txt"
	if canFiles() and isfile(path) then
		local ok, content = pcall(readfile, path)
		if ok and content ~= "" then
			return content
		end
	end
	return nil
end

function Config:LoadAutoload()
	local name = Config:GetAutoload()
	if name then
		return Config:Load(name)
	end
	return false, "no autoload set"
end

function Config:Share()
	return Config:Encode()
end

-- Builds a ready-made "Settings" tab section (appearance + configs) on the given tab.
function Library:BuildSettings(tab, opts)
	opts = opts or {}
	local appearance = tab:AddSection({ Title = "Appearance", Icon = "palette" })
	appearance:AddSegmented({
		Text = "Mode",
		Flag = "_theme_mode",
		Values = Color.Modes,
		Default = Core.Mode,
		Callback = function(value)
			Library:SetTheme({ Mode = value }, true)
		end,
	})
	appearance:AddDropdown({
		Text = "Accent color",
		Flag = "_theme_preset",
		Values = Color.PresetNames(),
		Default = Core.Preset ~= "Custom" and Core.Preset or "Violet",
		Callback = function(value)
			Library:SetTheme({ Preset = value }, true)
		end,
	})
	appearance:AddColorPicker({
		Text = "Custom accent",
		Flag = "_theme_seed",
		Default = Core.Seed,
		Callback = function(color)
			Library:SetTheme({ Seed = color }, true)
		end,
	})
	appearance:AddSlider({
		Text = "Corner roundness",
		Flag = "_ui_corner",
		Min = 0,
		Max = 150,
		Default = Core.CornerScale * 100,
		Suffix = "%",
		Callback = function(value)
			Core.SetCornerScale(value / 100)
		end,
	})
	appearance:AddSlider({
		Text = "Interface scale",
		Flag = "_ui_scale",
		Min = 60,
		Max = 150,
		Default = math.floor(Util.Scale * 100 + 0.5),
		Suffix = "%",
		Callback = function(value)
			Library:SetScale(value / 100)
		end,
	})
	appearance:AddToggle({
		Text = "Animations",
		Description = "Disable for the snappiest feel on low-end devices.",
		Flag = "_ui_animations",
		Default = Util.AnimationsEnabled,
		Callback = function(value)
			Library:SetAnimations(value)
		end,
	})
	appearance:AddSlider({
		Text = "Animation speed",
		Flag = "_ui_speed",
		Min = 0.5,
		Max = 2,
		Step = 0.1,
		Default = Util.Speed,
		Suffix = "x",
		Callback = function(value)
			Library:SetAnimations(Util.AnimationsEnabled, value)
		end,
	})
	appearance:AddToggle({
		Text = "Ripple effect",
		Flag = "_ui_ripple",
		Default = Util.RippleEnabled,
		Callback = function(value)
			Library:SetRipple(value)
		end,
	})
	appearance:AddToggle({
		Text = "Rounded font",
		Description = "Google Sans Flex with soft terminals.",
		Flag = "_ui_rounded",
		Default = Assets.Rounded,
		Callback = function(value)
			Library:SetRoundedFont(value)
		end,
	})
	appearance:AddKeybind({
		Text = "Toggle menu key",
		Flag = "_ui_key",
		Default = Library.ToggleKey,
		Mode = "Press",
		Callback = function() end,
	})
	Core.Options["_ui_key"].Changed:Connect(function()
		local key = Core.Options["_ui_key"]:GetKey()
		if key and key.EnumType == Enum.KeyCode then
			Library.ToggleKey = key
		end
	end)

	Config:Ignore({ "_theme_mode", "_theme_preset", "_theme_seed" })
	if opts.Configs == false then
		return appearance
	end

	local configs = tab:AddSection({ Title = "Configuration", Icon = "save" })
	local nameInput = configs:AddInput({ Text = "Config name", Flag = "_cfg_name", Default = "default", Finished = true })
	local list = configs:AddDropdown({
		Text = "Saved configs",
		Flag = "_cfg_list",
		Values = Config:List(),
		AllowNull = true,
		Placeholder = "No configs yet",
	})
	local function refreshList()
		list:SetValues(Config:List(), true)
	end
	local function target()
		return list.Value or nameInput.Value
	end
	configs:AddButton({
		Text = "Save",
		Icon = "save",
		Style = "Filled",
		Callback = function()
			local name = nameInput.Value ~= "" and nameInput.Value or target()
			local ok, err = Config:Save(name)
			Library:Notify({
				Title = ok and "Config saved" or "Save failed",
				Content = ok and ("Saved '" .. name .. "'.") or tostring(err),
				Type = ok and "Success" or "Error",
			})
			refreshList()
		end,
	})
	configs:AddButton({
		Text = "Load",
		Icon = "download",
		Style = "Tonal",
		Callback = function()
			local name = target()
			local ok, err = Config:Load(name or "")
			Library:Notify({
				Title = ok and "Config loaded" or "Load failed",
				Content = ok and ("Loaded '" .. tostring(name) .. "'.") or tostring(err),
				Type = ok and "Success" or "Error",
			})
		end,
	})
	configs:AddButton({
		Text = "Delete",
		Icon = "delete",
		Style = "Outlined",
		Callback = function()
			local name = target()
			if not name or name == "" then
				return
			end
			Library:Dialog({
				Title = "Delete '" .. name .. "'?",
				Content = "This cannot be undone.",
				Icon = "delete",
				Buttons = {
					{ Text = "Cancel", Style = "Text" },
					{
						Text = "Delete",
						Style = "Danger",
						Callback = function()
							Config:Delete(name)
							refreshList()
						end,
					},
				},
			})
		end,
	})
	configs:AddToggle({
		Text = "Autoload selected config",
		Flag = "_cfg_autoload",
		Default = Config:GetAutoload() ~= nil,
		Callback = function(value)
			Config:SetAutoload(value and target() or nil)
		end,
	})
	configs:AddButton({
		Text = "Copy config to clipboard",
		Icon = "content_copy",
		Style = "Text",
		Callback = function()
			local copy = executorFn("setclipboard")
			if copy then
				copy(Config:Share())
				Library:Notify({ Title = "Copied", Content = "Config JSON copied to the clipboard.", Type = "Success", Duration = 3 })
			else
				Library:Notify({ Title = "Unavailable", Content = "Your executor has no setclipboard.", Type = "Warning" })
			end
		end,
	})
	Config:Ignore({ "_cfg_name", "_cfg_list", "_cfg_autoload" })
	return configs
end

--// Teardown \\--
function Library:Unload()
	if Library.Unloaded then
		return
	end
	Library.Unloaded = true
	Library.Unloading:Fire()
	Core.ClosePopups()
	maid:Clean()
	for control in table.clone(Core.Controls) do
		pcall(function()
			control:Destroy()
		end)
	end
	table.clear(Core.Controls)
	table.clear(Core.Options)
	table.clear(Core.Flags)
	if Library.Window then
		pcall(function()
			Library.Window:Destroy()
		end)
		Library.Window = nil
		Core.Window = nil
	end
	if Core.ScreenGui then
		Core.ScreenGui:Destroy()
		Core.ScreenGui = nil
	end
	Library.Root = nil
	Core.Overlay = nil
	initialised = false
	local env = typeof(getgenv) == "function" and getgenv() or nil
	if env and env.ZaridiumUI == Library then
		env.ZaridiumUI = nil
	end
end

function Library:GetAssetStatus()
	return Assets.Status
end

function Library:IsLoaded()
	return initialised and not Library.Unloaded
end

return Library

end

return require("Library")
